import { one, type Chapter } from "../../schema";
function ch(
  id: string,
  number: number,
  title: string,
  heading: string,
  paragraphs: Chapter["paragraphs"],
): Chapter {
  return { id, number, title, heading, paragraphs };
}

export const prideChapters: Chapter[] = [
  ch("cap-10", 10, "Caput X", "De primo superbiae gradu, qui est curiositas", [
    one(
      "p28",
      "28",
      "Primus itaque superbiae gradus est curiositas. Hanc autem talibus indiciis deprehendes: si videris monachum, de quo prius bene confidebas, ubicumque stat, ambulat, sedet, oculis incipientem vagari, caput erectum, aures portare suspensas, e motibus exterioris hominis interiorem immutatum agnoscas. Vir quippe perversus nictat oculo, terit pede, digito loquitur, et ex insolenti corporis motu, recens animae morbus deprehenditur, quam, dum a sui circumspectione torpescit incuria sui, curiosam in alios facit. Quia enim seipsam ignorat, foras mittitur, ut haedos pascat. Haedos quippe, qui peccatum significant, recte oculos auresque appellaverim, quoniam sicut mors per peccatum in orbem, sic per has fenestras intrat ad mentem. In his ergo pascendis se occupat curiosus, dum scire non curat qualem se reliquerit intus. Et vere si te vigilanter, homo, attendas, mirum est si ad aliud umquam intendas. Audi, curiose, Salomonem; audi, stulte, Sapientem: Omni custodia, inquit, custodi cor tuum, ut omnes videlicet sensus tui vigilent ad id, unde vita procedit, custodiendum. Quo enim a te, o curiose, recedis? Cui te interim committis? Ut quid audes oculos levare ad caelum, qui peccasti in caelum? Terram intuere, ut cognoscas te ipsum. Ipsa te tibi repraesentabit, quia terra es et in terram ibis.",
      "The first degree of pride is curiosity. This you may detect by the following signs. Look at that monk, whom you have hitherto supposed to be a sensible man. He has now taken to staring about him, whether he is standing up, walking about or sitting down. He thrusts his head forward, and pricks up his ears. From his outward movements you can clearly see the inward change that he has undergone. For it is the froward man who winketh with the eye, presseth with the foot, and speaketh with the finger, and from the unusual movements of his body is seen to have lately contracted disease of the soul — the careless sluggishness of which in self-examination makes it inquisitive about others. So since it takes no heed to itself it is sent out of doors to feed the kids. And as these are the types of sin, I may quite correctly give the title of 'kids' to the eyes and the ears, since as death comes into the world through sin, so does sin enter the mind through these apertures. The curious man, therefore, busies himself with feeding them, though he takes no trouble to ascertain the state in which he has left himself. Yet if, O man, you look carefully into yourself, it is indeed a wonder that you can ever look at anything else. You inquisitive fellow, listen to Solomon —you silly fellow, hearken to the wise man, as he says, With all watchfulness guard thy heart, in other words, keep all your senses on the watch to protect that which is the source of life. For whither, inquisitive man, will you retire from your own presence — to whom will you in the meantime intrust yourself? How dare you, who have sinned against heaven, lift up your eyes to the sky? Look down to the earth if you want to recognize yourself. It will show you what you are, for earth thou art, and to earth shalt thou go.",
      "The first degree of pride, then, is curiosity. And you will catch this by such signs: if you shall have seen a monk, of whom you previously well trusted, wherever he stands, walks, sits, beginning to wander with the eyes, the head erect, carrying the ears suspended, from the motions of the exterior man you may recognize the interior changed. For a perverse man winks with the eye, rubs with the foot, speaks with the finger, and from the insolent motion of the body a recent disease of the soul is caught, which, while it grows numb from circumspection of itself by carelessness of itself, makes it curious toward others. Because it does not know itself, it is sent outside, to feed the kids. Kids indeed, who signify sin, I would rightly have called eyes and ears, since as death through sin into the world, so through these windows it enters to the mind. In feeding these, then, the curious man occupies himself, while he does not care to know of what sort he has left himself within. And truly if you attend to yourself vigilantly, man, it is a wonder if you ever intend toward another thing. Hear, curious one, Solomon; hear, fool, the Wise: With all custody, he says, guard your heart. that namely all your senses may watch toward guarding that from which life proceeds. For whither do you withdraw from yourself, O curious one? To whom do you meanwhile commit yourself? Why do you dare to lift eyes to heaven, you who have sinned against heaven? Look upon the earth, that you may know yourself. It will present you to yourself, because you are earth and you will go into the earth.",
      [
        {
          kind: "word",
          title: "curiositas / inquisitive",
          body: "Bernard’s first step is curiositas. Mills often says ‘inquisitive’. The close line keeps curious so the later Lucifer material and the retractatio’s Seraphim remain one vice.",
        },
      ],
    ),
    one(
      "p29",
      "29",
      "Duabus tamen ex causis inculpabiliter oculos levas, ut vel petas auxilium, vel impendas. Levavit oculos suos David in montes, ut peteret; levavit et Dominus super turbas, ut impenderet: alter miserabiliter, alter misericorditer, ambo inculpabiliter. Tu quoque si locum, tempus et causam considerans, tua vel fratris necessitate oculos levas, non solum non culpo, sed et plurimum laudo. Hoc enim excusat miseria, illud commendat misericordia. Sin alias, non Prophetae, non Domini, sed Dinae aut Evae, immo ipsius Satanae imitatorem te dixerim. Dina namque, dum ad pascendos haedos egreditur, ipsa patri, et sua sibi virginitas rapitur. O Dina, quid necesse est ut videas mulieres alienigenas? Qua necessitate? Qua utilitate? An sola curiositate? Etsi ut otioso videris. Tu curiose spectas, sed curiosius spectaris. Quis crederet tunc illam tuam curiosam otiositatem, vel otiosam curiositatem, fore post sic non otiosa, sed tibi, tuis, hostibusque tam perniciosam?",
      "Now there are two reasons for which you may raise your eyes without being to blame for so doing — one is to seek, the other is to render, assistance. David raised his eyes to the mountains for the former, the Lord lifted His over the crowd for the latter purpose. The motive of the one was misfortune, that of the other was mercy, neither was to blame. If you likewise with due regard to place, time and occasion, look up when you or a brother are in distress, I not only do not blame you, I highly commend you. For misfortune allows the one action, mercy approves the other. But in different circumstances I should call you an imitator not of the Prophet nor of the Lord, but of Dina or of Eve, aye, verily, of Satan himself. For Dina when she went out to feed her kids, was snatched away from her father and her maidenhood was taken from her. O Dina, what need was there for thee to look on strange women? Was it necessary — did it serve any useful purpose — or was it done out of mere curiosity? Thy look may have no purpose, but it is not without purpose that men gaze on thee. There is curiosity in thy look, but more in the look that is turned on thee. Who could have supposed that thy curious carelessness or careless curiosity would afterwards prove to be not reckless but ruinous to thee, thy friends and thine enemies?",
      "Yet from two causes you lift the eyes without blame, that you may either ask help, or bestow it. David lifted his eyes to the mountains, that he might ask; the Lord also lifted them over the crowds, that he might bestow: the one miserably, the other mercifully, both without blame. You also, if considering place, time and cause, you lift the eyes by your necessity or a brother’s, I not only do not blame, but I also praise greatly. For misery excuses this, mercy commends that. But if otherwise, I would have called you an imitator not of the Prophet, not of the Lord, but of Dinah or of Eve, nay of Satan himself. For Dinah, while she goes out to feed the kids, herself is snatched from her father, and her virginity from herself. O Dinah, what need is there that you see foreign women? By what necessity? By what usefulness? Or by curiosity alone? Even if you seem to look as an idle one. You look curiously, but more curiously you are looked at. Who would have believed then that that curious idleness of yours, or idle curiosity, would afterwards be thus not idle, but so ruinous to you, to yours, and to enemies?",
    ),
    one(
      "p30",
      "30",
      "Tu quoque, o Eva, in paradiso posita es, ut cum viro tuo opereris et custodias illum, si iniunctum perfeceris, quandoque transitura ad melius, ubi nec opus sit te in aliquo opere occupari, nec de custodia sollicitari. Omne lignum paradisi ad vescendum tibi conceditur, praeter illud quod dicitur scientiae boni et mali. Si enim cetera bona sunt et sapiunt bonum, quid opus est edere de ligno, quod sapit etiam malum? Non plus sapere, quam oportet sapere. Sapere enim malum, sapere non est, sed desipere. Serva ergo commissum, exspecta promissum; cave prohibitum, ne perdas concessum. Quid tuam mortem tam intente intueris? Quid illo tam crebro vagantia lumina iacis? Quid spectare libet, quod manducare non licet? \"Oculos\", inquis, \"tendo, non manum. Non est interdictum ne videam, sed ne comedam. An non licet oculos quo volo levare, quos Deus in mea posuit potestate\"? Ad quod Apostolus: Omnia mihi licent, sed non omnia expediunt. Etsi culpa non est, culpae tamen indicium est. Nisi enim mens minus se curiose servaret, tua curiositas tempus vacuum non haberet. Etsi culpa non est, culpae tamen occasio est, et indicium commissae, et causa est committendae. Te enim intenta ad aliud, latenter interim in cor tuum serpens illabitur, blande alloquitur. Blanditiis rationem, mendaciis timorem compescit: \"Nequaquam\", inquiens, \"morieris\". Auget curam, dum incitat gulam; acuit curiositate, dum suggerit cupiditatem. Offert tandem prohibitum, et aufert concessum: porrigit pomum, et surripit paradisum. Hauris virus peritura, et perituros paritura. Perit salus, non destitit partus. Nascimur, morimur: ideoque nascimur morituri, quia prius morimur nascituri. Propterea grave iugum super omnes filios tuos usque in hodiernum diem.",
      "And thou, O Eve, wast placed in Paradise, that thou mightest work with thine husband and bestow thy care on him; and if thou hadst discharged thy duty, thou wouldst eventually have passed into a better sphere where there would have been no need for thee to be engaged in any work, or to be beset by any care. been impossible, St. Bernard expresses this more fully in his treatise 'Grace and Free Will,' caps, vii and viii. Leave was given to thee to eat of every tree in Paradise, except that one which is called the tree of knowledge of good and evil. For if the others are good and have a good savour, what need is there to eat of one which also has an evil savour? Not to be more wise than it behoveth to be wise. For to know evil is not knowledge but folly. So preserve what is given, await what is promised, avoid what is forbidden, lest thou lose what is allowed. Why lookest thou so eagerly for thy death? Why dost thou so often cast in that direction those wandering eyes of thine? What pleasure hast thou in looking on that which thou mayest not eat? Perchance thou dost reply, 'I stretch forth mine eyes not my hand. It is not looking but eating that is forbidden. May I not turn those eyes which God has placed under my control in any direction that I please?' To which the Apostle shall answer, All things are lawful for me, but all things are not expedient. Although it may not be in itself a guilty act, it affords an incentive to sin. For if thy mind had not shown insufficient attention to its own condition, it would have had no time for idle curiosity. Although there may be no offence, there is an opportunity as well as a suggestion to offend and a reason for offending. Vulgate, has the double sense of 'taste' and 'be wise'. For while thou art thinking of something else, the serpent creeps craftily into thine heart, and addresses thee in an alluring tone. He overcomes thy reason with his enticements, allays thy fear with falsehoods, and tells thee that thou art in no danger of death. He increases thy distress, as he stimulates thine appetite; he sharpens curiosity and strengthens desire. At length he offers what is forbidden and takes away what is allowed. He presents thee with fruit and deprives thee of Paradise. Thou takest poison: thou wilt perish thyself and wilt bring forth children who will perish. Thou hast sacrificed salvation, without losing the power to give birth. We are born, we die and thus we are born only to die, because we are dead before we are born.",
      "You also, O Eve, are placed in paradise, that you may work with your man and guard it, if you shall have completed what was enjoined, sometime about to pass over to a better, where there may be no need for you to be occupied in any work, nor to be anxious about custody. Every tree of paradise is granted you for eating, except that which is called of the knowledge of good and evil. For if the rest are good and taste of good, what need is there to eat of a tree that tastes also of evil? Not to taste/be-wise more than it is fitting to be wise. For to taste evil is not to be wise, but to be unwise. Keep therefore what was committed, wait for what was promised; beware the forbidden, lest you lose the granted. Why do you look so intently on your death? Why do you so often cast wandering lights upon that? Why is it pleasing to look at what it is not permitted to eat? ‘The eyes,’ you say, ‘I stretch, not the hand. It is not forbidden that I may not see, but that I may not eat. Or is it not permitted to lift the eyes where I wish, which God placed in my power?’ To which the Apostle: All things are permitted me, but not all things are expedient. Even if it is not a fault, it is nevertheless a sign of a fault. For unless the mind were guarding itself less curiously, your curiosity would not have empty time. Even if it is not a fault, it is nevertheless an occasion of a fault, and a sign of one committed, and a cause of one to be committed. For you, intent on another thing, the serpent meanwhile secretly slips into your heart, speaks blandly. By blandishments he checks reason, by lies fear: ‘By no means,’ saying, ‘will you die.’ He increases care, while he incites the gullet; he sharpens by curiosity, while he suggests cupidity. At last he offers the forbidden, and takes away the granted: he holds out an apple, and steals paradise. You drink the poison, about to perish, and about to bear those who will perish. Salvation perishes, birth did not cease. We are born, we die: and therefore we are born about to die, because first we die about to be born. Therefore a heavy yoke upon all your sons even unto this day.",
    ),
    one(
      "p31",
      "31",
      "Sed et tu, signaculum similitudinis, non in paradiso, sed in deliciis paradisi Dei positus es. Quid amplius quaerere debes? Plenus ergo sapientia et perfectus decore, altiora te ne quaesieris et fortiora te ne scrutatus fueris. Sta in te, ne cadas a te, si ambulas in magnis et in mirabilibus super te. Sed quid interim ex obliquo intendis ad aquilonem? Iam te video, iam te perspicio nescio quae supra te curiosius alta rimantem. Ponam, inquis, sedem meam ad Aquilonem. Ceteris astantibus caelicolis, dum tu sedere solus affectas, fratrum concordiam, totius caelestis patriae pacem ipsius, quantum in te est, quietem Trinitatis infestas. Quo te tua, miser, curiositas ducit, ut praesumptione singulari non dubites civibus scandalum, iniuriam facere Regi? Millia millium ministrant ei, et decies centena millia assistunt ei, ubi nemo sedere perhibetur, nisi solus is qui sedet super Cherubim, cui a ceteris ministratur; et tu nescio quae prae ceteris differentius prospiciendo, curiosius inquirendo, irreverentius pervadendo, sedem tibi collocas in caelo, ut sis similis Altissimo? Quo fine? Qua fiducia? Metire, insipiens, vires pensa finem, excogita modum. Sciente hoc Altissimo praesumis, an nesciente? Volente, an nolente? Sed quomodo malum quodcumque machinaris, aut velle, aut ignorare potest, cuius optima voluntas, cuius perfecta scientia est? Numquid autem et scire, et nolle non dubitas, sed non posse resistere putas? At vero nisi te conditum esse dubitaveris, dubitare te non crediderim de omnipotentia, sive de omnimoda scientia ac bonitate Conditoris, qui te de nihilo potuit, talem scivit, tantum condere voluit. Quomodo ergo Deum consentire aestimas, quod fieri nolit, ac refellere possit? An forte in te video compleri, immo a te initiari, quod post te ac per te a tui similibus in terris frequentatum solet vulgariter dici: Privatus dominus temerarios nutrit? An oculus tuus nequam est, quia ille bonus? De cuius bonitate dum fiduciam nefariam sumis, factus es et contra scientiam impudens, et contra potentiam audax.",
      "And as for thee, 'pattern of perfection,' thou wast placed not in Paradise, but in Eden the garden of God. What more couldst thou reasonably desire? Filled with wisdom, and exalted in honour, thou shouldst have expected nothing higher and worked for nothing stronger than thyself. Remain where thou art, lest thou fall from thy position, if thou walkest among things that are too great and wonderful for thee. But why dost thou sometimes turn round and look to the north? 1 Ezek. xxviii. 12, 13. I have given 'pattern of perfection ' as best conveying the sense of the expression used in the Vulgate, signaculum similitiidinis (lit. 'seal of resemblance', Douai version). The phrase is taken from the Septuagint, and its sense is much the same as that of the English versions 'thou sealest up the sum', viz. thou reachest the highest honour. The allusion of Ezekiel is to the Prince of Tyre, and is a warning that his ruin will be as complete as his greatness. He is regarded by the Fathers as a type of Satan. I see thee, I already detect thee peering too inquisitively into the unknown heights above thee, I will place sayest thou, my throne towards the north. The other dwellers in heaven are standing, whilst thou alone dost desire to sit, and dost thereby disturb the harmony of the brethren, the peace of the whole heavenly community, and, so far as it lies in thy power to do so, the tranquillity of the Trinity, Does this curiosity carry thee so far, thou wretched being, that with unrivalled presumption thou dost not scruple to give offence to the citizens and to do injury to the king? Thousands of thousands minister to him and ten times a hundred thousand stand before him, where no one is allowed to sit, but He alone who sitteth upon the cherubims and receiveth the ministrations of others. And dost thou — how shall I put it — claiming a wider outlook, a more incisive scrutiny and a freer entrance than that of the others, place a seat for thyself in heaven, that thou mayest be on a level with the Most High? Latin, which runs: 'I will place my seat above the stars of God, I will sit on a high mountain, on the high mountains in the north.' The quotation must have been purposely made in this form, as St. Bernard repeats it later in this chapter, and in one of his Sermons, (on the first Sunday in November, ii, para. 5) but gives it correctly in another one (on Ps. xci (Vulg. xc.) Serm. xi, para. 4). thousand'. In the Vulgate of Rev. v. 11 the words are omitted. What is thine object — on what dost thou rely? Thou fool, estimate thy powers, think of the result, consider the process. Dost thou presume on the knowledge or on the ignorance — on the willingness or on the reluctance — of the Most High? But how can He whose purpose is all good, and whose knowledge is unlimited, either consent to or be unaware of, thine evil design? Dost thou think that though He undoubtedly knows and disapproves it, He is unable to prevent it? But unless indeed thou art doubtful whether thou art a created being, I cannot suppose that thou canst doubt the omnipotence, omniscience and excellence of thy Creator, seeing that He was able to create thee out of nothing, and, knowing what thou wouldst turn out to be, willed to make thee the powerful being that thou art. When therefore thou thinkest that God will tolerate that of which He disapproves and has the power to prohibit, do I perchance see in thee the completion — aye, and the origin — of that idea which after thee and because of thee is constantly held by those like thee on earth, and which is embodied in the common saying, 'An usurper keeps reckless followers?' Is thine eye evil because he is good? This wicked presumption of thine on His benevolence has produced in thee an insolent disregard of His knowledge, and a daring defiance of His power.",
      "But you also, seal of likeness, are placed not in paradise, but in the delights of the paradise of God. What more ought you to seek? Full therefore of wisdom and perfect in beauty, do not seek things higher than you and do not have scrutinized things stronger than you. Stand in yourself, lest you fall from yourself, if you walk in great and wonderful things above you. But why meanwhile do you intend from the side toward the north? Already I see you, already I look through you searching too curiously I know not what high things above you. I will place, you say, my seat toward the North. The other heaven-dwellers standing by, while you alone desire to sit, you assail the concord of the brothers, the peace of the whole heavenly homeland, the rest of the Trinity itself, as much as is in you. Whither does your curiosity, miserable one, lead you, that by a singular presumption you do not hesitate to make scandal for the citizens, injury for the King? Thousands of thousands minister to him, and ten times a hundred thousand stand by him, where no one is reported to sit, except he alone who sits upon the Cherubim, to whom it is ministered by the rest; and you, looking out I know not what more differently before the rest, inquiring more curiously, invading more irreverently, place a seat for yourself in heaven, that you may be like the Most High? With what end? With what trust? Measure, unwise one, your strengths, weigh the end, think out the measure. Do you presume with the Most High knowing this, or not knowing? Willing, or unwilling? But how can he either will, or not know, whatever evil you machinate, whose will is best, whose knowledge is perfect? Or do you not doubt that he both knows and does not will, but think he cannot resist? But unless you shall have doubted that you were created, I would not have believed you to doubt about the omnipotence, or about the all-manner knowledge and goodness of the Creator, who was able to found you from nothing, knew to make you such, willed to found you so great. How then do you estimate that God consents to what he would not have done, and can refute? Or perhaps I see fulfilled in you — nay begun by you — what after you and through you is accustomed to be said commonly by those like you on the lands: A private lord nourishes the reckless? Or is your eye worthless, because he is good? From whose goodness, while you take a nefarious trust, you have been made both shameless against knowledge, and bold against power.",
    ),
    one(
      "p32",
      "32",
      "Hoc est enim, o impie, hoc est quod cogitas; haec est iniquitas, quam meditaris in cubili tuo, et dicis: \"Putas Creator opus suum destruat\"? Scio quidem quia non latet Deum qualiscumque cogitatio mea: Deus enim est. Nec placet ei talis cogitatio mea, quia bonus est. Sed nec si velit, ego effugiam manus eius, quia potens est. Numquid tamen mihi timendum est? Si enim cum bonus sit, non potest illi placere malum meum, quanto minus suum? Meum quippe dixerim contra eius voluntatem aliquid velle; suum autem, si vindicet sese. Tam ergo quodcumque scelus non valet velle ulcisci, quam nec vult, nec valet sua bonitate privari. Fallis te, miser, fallis te, non Deum. Te, inquam, fallis, et mentitur iniquitas sibi, non Deo. Dolose quidem agis, sed in conspectu eius. Te ergo fallis, non Deum. Et quia de magno eius bono in te, tu magnum in eum excogitas malum, merito iniquitas tua invenitur ad odium. Quae namque maior iniquitas, quam ut inde Creator a te contemnatur, unde plus amari merebatur? Quae maior iniquitas, quam cum de potentia Dei non dubites, quin te scilicet destruere possit, qui condere potuit, confisus tamen de multa eius dulcedine, qua speras eum nolle vindicare cum possit, mala pro bonis, odium retribuas pro dilectione?",
      "For this, and nothing less than this, thou unholy one, is thy train of thought. This is the wickedness that thou dost devise on thy bed, and sayest, 'thinkest thou that the Creator will destroy His own work? I am well aware that no thought of mine escapes God, because He is God, nor does any such thought please Him, because He is good. Nor can I escape His hand — if He so wishes — because He is mighty. But need this be a cause of dread to me? For if through His goodness He can have no pleasure in evil done by me — how much less can He derive it from evil action of His own? I should call it evil on my part to wish to oppose His will — and on His part to avenge Himself. He therefore cannot wish to take vengeance for any crime, since He neither will nor can part with His inherent goodness.' It is thyself thou — wretch, alone that thou deceivest, not God. Thou deceivest thyself, I repeat, and thy wickedness lies to thyself not to God. Thou dost indeed act deceitfully, but He detects thy motive. Thus thou deceivest thyself not God. And since in return for His great goodness, thou dost contemplate great evil towards Him, thy wickedness naturally leads thee to hate Him. For what can be more unjust than that the Creator should be scorned by thee for the very reason for which He most deserves thy love? What can be more outrageous than that when thou hast no doubt that the power of God shown in thy creation, could be used for thy destruction, thou dost yet rely on His abundant kindness, and that this should lead thee to hope that He will be unwilling to exercise His vindictive power? Wilt thou repay good with evil and love with hatred?",
      "For this is, O impious one, this is what you think; this is the iniquity which you meditate on your bed, and you say: ‘Do you think the Creator will destroy his work?’ I know indeed that whatever thought of mine is not hidden from God: for he is God. Nor does such a thought of mine please him, because he is good. But neither, if he should wish, shall I flee his hands, because he is powerful. Yet is it to be feared by me? For if, since he is good, my evil cannot please him, by how much less his own? Mine indeed I would have said is to will something against his will; his, if he should avenge himself. Therefore he is as unable to will to avenge any crime, as he neither wills nor is able to be deprived of his goodness. You deceive yourself, miserable one, you deceive yourself, not God. Yourself, I say, you deceive, and iniquity lies to itself, not to God. You act deceitfully indeed, but in his sight. You therefore deceive yourself, not God. And because from his great good in you, you think out a great evil against him, deservedly is your iniquity found unto hatred. For what greater iniquity, than that the Creator should be contemned by you from that whence he more deserved to be loved? What greater iniquity, than that, when you do not doubt about the power of God, that namely he who was able to found you can destroy you, yet trusting in his much sweetness, by which you hope he is unwilling to avenge when he can, you repay evils for goods, hatred for love?",
    ),
    one(
      "p33",
      "33",
      "Haec, inquam, iniquitas, non ira momentanea, sed odio digna est sempiterno, qua tuo dulcissimo et altissimo Domino, licet invito, desideras tamen ac speras aequari, quatenus semper videat quod doleat, dum te socium habeat cum nolit, nec deiciat cum possit; quin potius eligat ipse dolere, quam te patiatur perire; possit quidem deicere si velit, sed prae dulcedine, ut aestimas, velle non possit. Certe si talis est qualem putas, tanto nequius agis, si non amas. Et si ille aliquid fieri patitur contra se, potius quam ipse aliquid faciat contra te, quanta malitia est, ut vel tu non parcas illi, qui sibi non parcit, parcendo tibi? Absit tamen ab eius perfectione, ut qua dulcis est, iustus non sit, quasi simul dulcis et iustus esse non possit, cum melior sit iusta dulcedo quam remissa, immo virtus non sit dulcedo sine iustitia. Quia igitur gratuitae Dei bonitati, qua gratis factus es, ingratus exsistis, iustitiam vero quam expertus non es, non metuis; ideoque audacter committis culpam, de qua tibi falso promittis impunitatem. Iam ecce iustum senties, quem bonum nosti, cadens in foveam, quam paras auctori, ut dum scilicet talem in eum poenam machinaris, qua tamen valeat carere, si velit, sed, ut putas, non valeat velle, et ideo nec carere ea utique bonitate, qua neminem expertus es illum punisse: talem iustus Deus iustissime in te retorqueat poenam, qui nec valet, nec debet pati suam impune bonitatem offendi, sic utique temperans in vindicta sententiam, ut, si velis resipiscere, non neget veniam, secundum tamen duritiam tuam et cor impaenitens, non possis velle, et ideo nec poena carere.",
      "Now I say that this malice is deserving, not of passing indignation but of abiding wrath. For it is thy desire and hope to be on an equality with the most gracious and most high Lord, although that is not His wish. Thou desirest that He shall have always before His eyes the distressing sight of thine unwelcome presence, and thou thinkest that though He is able to cast thee down, He will not do so, but that He will prefer Himself to suffer than to allow thee to perish. It is undoubtedly in His power to overthrow thee, if such be His will — but in thine opinion His kindness will not allow Him to entertain such a wish. If He be such as thou supposest Him to be, it is clear that thy conduct in not loving Him is so much the baser. And if He does allow action to be taken against Himself rather than take action against thee — how great must be thy malice in having no consideration for Him who disregards Himself in sparing thee? 1. Ps. cix. (cviii. Vulg.) 5. But it is inconceivable that He who is perfect can fail to be both kind and just. It is not as though kindness and justice cannot exist together. Kindness is really better when it is just than when it is slack — nay more, kindness without justice is not a virtue. It therefore appears that thou remainest ungrateful for the loving-kindness of God whereby thou wast created without exertion on thy part, but thou fearest not His justice of which thou hast had no experience, and dost therefore audaciously incur guilt for which thou dost falsely promise thyself impunity. Now mark that thou wilt find Him whom thou hast known to be kind, to be also righteous, and thou wilt thyself fall into the ditch which thou hast dug for thy Creator. Thy design seems to be to inflict on Him an injury which He is able to avoid if He wishes to do so a wish which thou thinkest that He cannot entertain, as He will not be wanting in that kindness which has led Him never within thine experience to punish anybody. The righteous God will most justly retaliate by punishing thee, since He neither can nor ought to allow such a slight on His goodness to remain unpunished. He may, however, so moderate the severity of His sentence that, if thou art willing to return to reason, He will not refuse thee pardon. But such is thy hardness and impenitent heart, that thou art incapable of such a wish, and therefore canst not escape the penalty.",
      "This iniquity, I say, is worthy not of a momentary anger but of everlasting hatred, by which you desire and hope to be equalled to your sweetest and highest Lord, though unwilling, so that he may always see what he may grieve, while he has you as a partner when he does not will, nor casts you down when he can; nay rather he himself chooses to grieve, than that he should suffer you to perish; he can indeed cast down if he will, but before sweetness, as you estimate, he cannot will. Certainly if he is such as you think, you act so much more wickedly if you do not love. And if he suffers something to be done against himself, rather than he himself do something against you, how great is the malice, that you at least do not spare him who does not spare himself, by sparing you? Yet far be it from his perfection, that by that by which he is sweet he should not be just, as if he could not be sweet and just at once, since a just sweetness is better than a remiss one, nay sweetness without justice is not a virtue. Because therefore you exist ungrateful to the gratuitous goodness of God, by which you were made gratis, and you do not fear the justice which you have not experienced; and therefore you boldly commit a fault, about which you falsely promise yourself impunity. Already behold you will feel just him whom you knew good, falling into the pit which you prepare for the author, so that namely while you machinate against him such a punishment, which nevertheless he is able to be without if he will, but, as you think, is not able to will, and therefore neither to be without that goodness, by which you have experienced him to have punished no one: such a punishment let the just God most justly twist back upon you, who neither is able nor ought to suffer his goodness to be offended with impunity, so tempering the sentence in vengeance that, if you should will to come to your senses, he may not deny pardon, yet according to your hardness and impenitent heart you cannot will, and therefore neither be without the punishment.",
    ),
    one(
      "p34",
      "34",
      "Sed iam audi calumniam: Caelum, inquit, mihi sedes est, terra autem scabellum pedum meorum. Non dixit \"Oriens\" aut \"Occidens\" aut una aliqua caeli plaga, sed \"totum caelum mihi sedes est\". Non potes ergo in parte sedere caeli, cum ille totum elegerit sibi. In terra non potes, quia pedum eius scabellum est. Terra etenim locus solidus est, ubi sedet Ecclesia, fundata supra firmam petram. Quid facies? E caelo pulsus, in terris remanere non potes. Elige ergo tibi in aere locum, non ad sedendum, sed ad volandum, ut qui tentasti concutere statum aeternitatis, poenam sentias propriae fluctuationis. Te ergo fluctante inter caelum et terram sedet Dominus super solium excelsum et elevatum, et plena est omnis terra maiestate eius, ut nusquam nisi in aere invenias locum.",
      "But now listen to the accusation against thee. Heaven, saith He, is my throne and the earth my footstool. He did not say 'east' or 'west', or any one region in the heaven, but the whole heaven is my throne. Thou must not therefore seat thyself in a portion of the heaven, since He has chosen the whole of it for Himself. Thou canst not place thyself on earth, for it is His footstool. For the earth is a solid body, on which is seated the Church, founded on a strong rock. What wilt thou do? Driven out of heaven, thou canst not remain on earth. Choose then for thyself a place in the air, not for session but for flight, so that thou, who didst attempt to shatter the security of eternity, shall pay the penalty of thine own unrest. For, whilst thou art driven to and fro between Heaven and earth, the Lord is seated on a throne high and elevated and the whole earth is full of His majesty — so that thou canst find no place except in the air.",
      "But now hear the calumny: Heaven, he says, is a seat for me, but the earth the footstool of my feet. He did not say ‘East’ or ‘West’ or some one region of heaven, but ‘the whole heaven is a seat for me.’ You cannot therefore sit in a part of heaven, since he has chosen the whole for himself. On earth you cannot, because it is the footstool of his feet. For the earth is a solid place, where the Church sits, founded above a firm rock. What will you do? Driven from heaven, you cannot remain on the lands. Choose therefore for yourself a place in the air, not for sitting, but for flying, that you who tried to shake the standing of eternity may feel the punishment of your own fluctuation. You therefore fluctuating between heaven and earth, the Lord sits upon a throne high and lifted, and the whole earth is full of his majesty, so that nowhere except in the air may you find a place.",
    ),
    one(
      "p35",
      "35",
      "Seraphim namque aliis quidem alis suae contemplationis de throno ad scabellum, de scabello ad thronum volantia, aliis caput Domini pedesque velantia, ad hoc ibi posita puto, ut sicut peccanti homini paradisi per Cherubim prohibetur ingressus, ita et per Seraphim suae curiositati modus imponatur, quatenus nec caeli iam magis impudenter quam prudenter arcana rimeris, nec Ecclesiae mysteria cognoscas in terris, sed solis contentus sis cordibus superborum, qui nec in terra esse dignantur sicut ceteri hominum, nec sicut angeli volant ad caelum. Licet vero et caput in caelo, et pedes in terra a te abscondantur, quiddam tamen tibi medium videndum ad invidendum dumtaxat permittitur, dum suspensus in aere, descendentes quidem per te et ascendentes angelos intueris, sed quid vel audiant in caelis, vel nuntient terris, penitus nescis.",
      "For the Seraphim with their wings of contemplation fly from the throne to the footstool, and from the footstool to the throne, while with their other wings they cover the head and feet of the Lord. And I think that they are purposely so placed that, as the access to Paradise was barred against sinful men by the Cherubim, so also shall a limit be set to thy curiosity by the Seraphim. The result will be that thou wilt no longer, with more impudence than prudence, investigate the secrets of heaven, nor wilt thou discover the mysteries of the Church on earth, but shalt find a home only in the hearts of the proud, who neither deign to live on earth like other men, nor fly like the angels to heaven. But although His head is hidden from thee in heaven and His feet on earth, thou mayest as it were be allowed to see — and to envy — some part of what lies between, whilst thou art suspended in the air, and dost behold the angels descending and ascending past thee, though thou art altogether ignorant of what they hear in heaven or tell on earth.",
      "For the Seraphim, flying with certain wings of their contemplation from the throne to the footstool, from the footstool to the throne, covering with others the Lord’s head and feet, I suppose were placed there for this, that as for the sinning man the entry of paradise is forbidden through the Cherubim, so also through the Seraphim a measure may be imposed on his curiosity, so that you may neither already search the secrets of heaven more impudently than prudently, nor know the mysteries of the Church on the lands, but may be content with the hearts of the proud alone, who neither deign to be on earth as the rest of men, nor fly to heaven as angels. Yet although both the head in heaven and the feet on earth are hidden from you, something middle is nevertheless permitted you to be seen for envying only, while, suspended in the air, you look upon angels descending through you and ascending, but what they either hear in the heavens or announce to the lands you wholly do not know.",
      [
        {
          kind: "text",
          title: "puto and the retractatio",
          body: "Bernard later confessed he had never heard or read this opinion about the Seraphim, and that puto was meant as a conjecture. The close line keeps I suppose.",
        },
      ],
    ),
    one(
      "p36",
      "36",
      "O Lucifer, qui mane oriebaris, immo non iam lucifer, sed noctifer, aut etiam mortifer, rectus cursus tuus erat ab Oriente ad Meridiem, et tu praepostero ordine tendis ad Aquilonem? Quanto magis ad alta festinas, tanto celerius ad occasum declinas. Velim tamen curiosius, o curiose, intentionem tuae curiositatis inquirere. Ponam, inquis, sedem meam ad Aquilonem. Nec Aquilonem hunc corporalem, nec sedem hanc, cum sis spiritus, intelligo materialem. Puto autem per Aquilonem, reprobandos homines fuisse designatos, per sedem potestatem in illos. Quos utique in praescientia Dei, quanto ei vicinior, tanto ceteris perspicacior praevidens nullo quidem sapientiae radio coruscantes, nullo spiritus amore ferventes, velut vacuum repereris locum, affectasti super illos dominium, quos quadam tuae astutiae claritate perfunderes, tuae malitiae aestibus inflammares, ut quomodo Altissimus sua sapientia ac bonitate omnibus filiis oboedientiae praeerat, ita et tu super omnes filios superbiae rex constitutus, tua eos astuta malitia ac malitiosa astutia regeres, per quod Altissimo similis esses. Sed miror, cum in praescientia Dei tuum praevideris principatum, cur non eadem praevidisti et praecipitium? Nam si praevidisti, quae insania fuit, ut cum tanta miseria cuperes principari, ut malles misere praeesse, quam feliciter subesse? An non expediebat participem esse plagarum illarum luminosarum, quam principem tenebrarum harum? Sed credibilius est, quod non praevidisti: aut propter illam causam, quam superius dixi, quia Dei bonitatem attendens, dixisti in corde tuo: Non requiret (Psal. x, 13); propter quod, o impie, Deum irritasti; aut quia, viso principatu, statim in oculo superbiae trabes excrevit, qua interposita casum videre non potuisti.",
      "O Lucifer, thou who didst rise in the morning, surely a bearer no longer of light, but of night — aye, even of death — thy proper course was from the east to the south, and dost thou invert the order and perversely tend towards the north? In proportion to thy haste to rise is the rapidity of thy decline and fall. Yet, thou curious one, I should wish to investigate more closely the object of thy curiosity. I will place, sayest thou, my throne towards the north. And as thou art a spirit, I think that neither 'north' nor 'throne' is to be understood in a local or literal sense. For, I suppose that by 'the north' is meant evil men, and by 'my throne' thy control over them. For in the foreknowledge of God, thou hast from thy chosen proximity to Him, a clearer insight into the future than had others; and as these were neither enlightened by any ray of wisdom, nor warmed by the love of the spirit, thou didst find in them as it were thine opportunity. Thus didst thou establish thy rule over them, so that thou mightest pour into them some of thy clever cunning, and influence them with thy wicked warmth; so that as the Most High controlled all the sons of obedience by His wisdom and His goodness, thou mightest govern these by thy cunning wickedness and wicked cunning, and in this respect thou mightest resemble Him. But I am surprised that, since in God's foreknowledge thou didst foresee thy rule, thou didst not in like manner foresee thy ruin. For if thou didst foresee it, what madness it was to be so wickedly eager for dominion as to prefer rule and wretchedness to submission and happiness. Or was it not better for thee to be a partner in those regions of light than ruler of those dark places? But it is more likely that thou didst not look forward either for the reason which I gave above that in thy reliance on the kindness of God thou didst say in thine heart, He will not require it, and didst therefore wickedly offend Him, or because when thou didst see thy rule, the beam of pride at once rose up in thine eye which through its interference was unable to discern its danger.",
      "O Lucifer, who were rising in the morning — nay, no longer light-bearer, but night-bearer, or even death-bearer — your right course was from the East to the South, and you in inverted order stretch toward the North? By how much more you hasten to high things, by so much more swiftly you decline toward setting. I would nevertheless inquire more curiously, O curious one, into the intention of your curiosity. I will place, you say, my seat toward the North. I understand neither this North as bodily, nor this seat as material, since you are a spirit. But I suppose that through the North men to be rejected were designated, through the seat power over them. Whom indeed in the foreknowledge of God, as nearer to him, so more perspicacious than the rest, seeing them gleaming with no ray of wisdom, burning with no love of the spirit, you found as an empty place, you desired dominion over those whom you would flood with a certain brightness of your cunning, inflame with the heats of your malice, so that as the Most High by his wisdom and goodness was over all the sons of obedience, so you also, constituted king over all the sons of pride, might rule them by your cunning malice and malicious cunning, through which you would be like the Most High. But I wonder, when in the foreknowledge of God you foresaw your principate, why you did not by the same foresee also the precipice? For if you foresaw, what insanity was it, that with so great misery you desired to be prince, that you would rather miserably be over, than happily be under? Or was it not expedient to be a partner of those luminous regions, rather than prince of these darknesses? But it is more credible that you did not foresee: either on account of that cause which I said above, because attending to the goodness of God you said in your heart: He will not require it; on account of which, O impious one, you provoked God; or because, the principate having been seen, at once in the eye of pride a beam grew, which having been interposed you could not see the fall.",
    ),
    one(
      "p37",
      "37",
      "Sic Ioseph, cum praevidisset exaltationem suam, non tamen praescivit sui venditionem, quamvis propior esset venditio quam exaltatio. Non quod tantum Patriarcham in superbiam crediderim incidisse, sed ut eius exemplo pateat, quod hi qui futura praevident per spiritum prophetiae, etsi non omnia, non ideo tamen putandi sunt nulla vidisse. Quod si quis contendat, in eo quod sua somnia adhuc adolescentulus narrabat, quorum tunc mysterium ignorabat, vanitatem posse notari, ego tamen mysterio magis sive simplicitati pueri deputandum arbitror, quam vanitati; quae tamen, si qua fuit, per ea quae passus legitur, potuit expiari. Nonnullis enim aliqua aliquando de se per revelationem iucunda monstratur, quae etsi humanus animus absque ulla vanitate scire non potest, non minus ideo eveniet quod monstratum est, sic tamen ut illa vanitas impunita non sit, qua de magnitudine aut revelationis aut promissionis in se vel leviter exsultavit. Sicut enim medicus, non solum unguento, sed et igne utitur et ferro, quo omne quod in vulnere sanando superfluum excreverit, secet et urat, ne sanitatem, quae ex unguento procedit, impediat, sic medicus animarum Deus huiusmodi animae procurat tentationes, immittit tribulationes, quibus afflicta et humiliata, gaudium vertat in luctum, revelationem putet illusionem. Vnde fit ut et vanitate careat, et veritas revelationis non pereat. Sic Pauli extollentia per stimulos carnis reprimitur, et ipse revelationibus crebris attollitur. Sic Zachariae infidelitas linguae obligatione mulctatur, et Angeli veritas suo in tempore manifestanda non mutatur. Sic, sic per gloriam et ignobilitatem sancti proficiunt, dum inter singularia dona quae recipiunt, gratiam supra se aliquid cernunt, non obliviscantur quod sunt.",
      "In like manner Joseph did not foresee his sale though he had foreseen his promotion and this although the sale was to precede the promotion. I should not from this conclude that the great patriarch was guilty of pride, but that his experience proves that those who possess the spirit of prophecy must not be supposed to have foreseen nothing because they did not foresee everything. Some one may, perhaps, maintain that the fact that this youth recorded his dreams — of whose symbolic significance he was at the time unaware — was a mark of self-sufficiency. I still think that this should be ascribed to their symbolic character or to his boyish innocence, rather than to conceit. And if there were such conceit, he was able to atone for it by his subsequent painful experiences. For revelations of a character pleasing to themselves are sometimes made to certain persons, and though such knowledge must inevitably engender conceit in the human mind, the prediction may nevertheless be fulfilled — albeit in such a way that the vanity which has caused even a slight delight in the importance of the revelation shall not be unpunished. For a physician uses not only ointment but fire and iron, with which he cuts out or cauterizes everything which is useless for the treatment of the wound, so that there may be no obstacle to the remedial working of the ointment. In like manner does God as the physician of souls, prescribe and administer to a soul of such a disposition, temptations and troubles in order that, chastened and humbled, it may turn joy into sorrow, and think the revelation a delusion. The result is that vanity disappears, though the truth of the revelation is not impaired. Thus Paul's tendency to self-exaltation is checked by his thorn in the flesh, while he is himself uplifted repeated revelations. Thus want of faith in Zacharias is punished by loss of speech, yet the declaration of the angel that the truth would be made clear during his lifetime is unaltered. Thus again, by honour and dishonour do the saints make progress, though among the special gifts which each receives, they are only too well aware of the existence in them of that vanity which is common to mankind; so that while they know themselves to be the possessors of supernatural favour, they may ever remember whom they truly are.",
      "So Joseph, when he had foreseen his exaltation, nevertheless did not foresee his selling, although the selling was nearer than the exaltation. Not that I would have believed so great a Patriarch to have fallen into pride, but that by his example it may be open that those who foresee future things through the spirit of prophecy, even if not all things, are not therefore to be thought to have seen none. But if anyone contend that in this, that still an adolescent he was narrating his dreams, whose mystery he then did not know, vanity can be noted, I nevertheless judge it to be assigned more to the mystery or to the simplicity of the boy than to vanity; which nevertheless, if there was any, could be expiated through those things which he is read to have suffered. For to some, sometimes, some pleasant things about themselves are shown through revelation, which even if the human mind cannot know without any vanity, not less therefore will that which was shown come about, yet so that that vanity may not be unpunished, by which he exulted even lightly in himself about the greatness either of the revelation or of the promise. For as a physician uses not only ointment but also fire and iron, by which he may cut and burn whatever superfluous has grown in the wound to be healed, lest it impede the health which proceeds from the ointment, so God the physician of souls procures temptations of this kind of soul, sends tribulations, by which, afflicted and humbled, it may turn joy into mourning, may think the revelation an illusion. Whence it is made that it both lacks vanity, and the truth of the revelation does not perish. So Paul’s lifting-up is repressed by goads of the flesh, and he himself is lifted by frequent revelations. So Zachary’s unbelief is fined by the binding of the tongue, and the Angel’s truth, to be manifested in its time, is not changed. So, so through glory and ignobility the saints advance, while among the singular gifts which they receive, they discern a grace above themselves, they may not forget what they are.",
    ),
    one(
      "p38",
      "38",
      "Sed, quid de revelationibus ad curiositatem? De quibus, ut haec per excessum intermiscerem, inde occasio sumpta est, cum ostendere vellem, reprobum Angelum ante casum suum sic potuisse praevidere illam quam post accepit, in reprobos homines dominationem, ut tamen suam non praesciret damnationem. De quo etiam nonnullis quaestiunculis motis magis quam solutis, totius disputatiunculae haec summa sit: quod per curiositatem a veritate ceciderit, quia prius spectavit curiose, quod affectavit illicite, speravit praesumptuose. Iure igitur in gradibus superbiae primum curiositas vindicat sibi, quae etiam inventa est initium omnis esse peccati. Sed nisi haec citius cohibeatur, in levitatem animi, quae secundus gradus est, cito delabitur.",
      "But what about revelations to mere curiosity? I took the opportunity of dealing with these in a digression, when I tried to show that the wicked angel before his fall was allowed to foresee that dominion which he afterwards acquired over wicked men, but not to anticipate his own condemnation. That is a matter about which questions of small moment may be raised which it is easier to ask than to answer, and of which the sum and substance is but this that he fell from the truth because his idle speculation led him to unlawful desire and thus to presumptuous aspiration. Curiosity therefore rightly claims the first place among the degrees of pride, and is thus revealed as the beginning of all sin. But unless this is suppressed very speedily it will soon develop into a careless frame of mind which constitutes the second degree.",
      "But what about revelations toward curiosity? From which, that I might mix these in by a going-out, occasion was taken, when I wished to show that the reprobate Angel before his fall could so have foreseen that domination over reprobate men which he afterwards received, that nevertheless he would not foresee his own damnation. About which also, some little questions having been moved rather than solved, let this be the sum of the whole little disputation: that he fell from the truth through curiosity, because he first looked curiously at what he desired illicitly, hoped presumptuously. Rightly therefore in the degrees of pride does curiosity claim the first for itself, which has also been found to be the beginning of every sin. But unless this is more quickly restrained, it quickly slides down into lightness of mind, which is the second degree.",
    ),
  ]),
  ch("cap-11", 11, "Caput XI", "De secundo gradu superbiae, qui est levitas animi", [
    one(
      "p39",
      "39",
      "Monachus enim, qui sui negligens, alios curiose circumspicit, dum quosdam suspicit superiores, quosdam despicit inferiores, et in aliis quidem videt quod invidet, in aliis quod irridet. Inde fit ut pro mobilitate oculorum levigatus animus, nulla utique sui cura aggravatus, modo per superbiam ad alta se erigat, modo per invidiam in ima demergat: nunc per invidiam nequiter tabescit, nunc pro excellentia pueriliter hilarescit. In altero nequam, in altero vanus, in utroque superbus exsistit, quia et quod superari se dolet, et quod superare se gaudet, amor propriae excellentiae facit. Has autem animi vicissitudines nunc pauca et mordacia, nunc multa et inania, nunc risu, nunc luctu plena, semper vero irrationabilia indicant verba. Compara, si vis, hos duos primos superbiae gradus supremis duobus humilitatis, et vide si non in ultimo curiositas, in penultimo levitas cohibetur: idipsum in ceteris reperies, si alterutrum comparentur. Sed iam ad tertium docendo, non descendendo veniamus.",
      "For the monk who is careless about himself and unduly inquisitive about other people, looks up to some as his betters and looks down upon others as his inferiors — in some he sees cause for envy, while others are the objects of his scorn. It thus happens that his mind, enervated by his habit of staring about him, is oppressed by no anxiety on its own account, now through pride soars to the heights and then sinks through envy to the depths. He shows at one moment a sulky acquiescence in his own wickedness, at another a childish delight in his excellence. In the former he exhibits his weakness, in the latter his vanity, in both his pride; for it is love of his own excellence that gives him distress when others surpass him, and joy when he surpasses them. This unbalanced disposition shows itself in speech sometimes brief and bitter, sometimes full and feeble, alternately jocose and doleful, and always silly. Compare if you please these two earliest degrees of pride with the two highest degrees of humility, and see if the last one of these latter does not repress curiosity, and the one before it levity. You will find the same contrast if the other degrees are similarly compared. But now let us go on to the study of the third degree — without, however, falling into it.",
      "For the monk who, neglecting himself, looks curiously around at others, while he looks up to certain as superiors, looks down on certain as inferiors, and in some indeed sees what he envies, in others what he mocks. Thence it happens that the mind, made light by the mobility of the eyes, weighed down by no care of itself at all, now through pride raises itself to high things, now through envy sinks into the lowest: now through envy it wastes wickedly, now for excellence it grows boyishly cheerful. In the one worthless, in the other vain, in both he exists proud, because both that he grieves to be surpassed, and that he rejoices to surpass, the love of his own excellence makes. And these vicissitudes of mind now few and biting, now many and empty, now full of laughter, now of mourning, but always irrational, words indicate. Compare, if you wish, these first two degrees of pride with the highest two of humility, and see if curiosity is not restrained in the last, lightness in the last-but-one: you will find the very same in the rest, if they are compared each with each. But now let us come to the third by teaching, not by descending.",
    ),
  ]),
  ch("cap-12", 12, "Caput XII", "De tertio gradu superbiae, qui est inepta laetitia", [
    one(
      "p40",
      "40",
      "Proprium est superborum, laeta semper appetere et tristia devitare, iuxta illud: Cor stultorum, ubi laetitia. Vnde et monachus, qui duos iam superbiae gradus descendit, dum per curiositatem ad animi levitatem devenit, cum gaudium, quod semper appetit, frequenti videt interpolari tristitia, quam de bonis alterius contrahit, impatiens suae humiliationis, fugit ad consilium falsae consolationis. Ex illa denique parte, qua sua sibi vilitas et aliena excellentia monstratur, restringit curiositatem, ut totum se transferat in contrariam partem, quatenus in quo ipse videtur praecellere, curiosius notet, in quo alter praecellit, semper dissimulet, ut dum devitat quod triste putatur, laetitia continuetur. Sicque fit, ut quem sibi vicissim vindicabant gaudium et tristitia, sola possidere incipiat inepta laetitia. In hac autem tertium tibi gradum constituo: accipe quibus eam signis vel in te deprehendas vel in altero. Illum qui eiusmodi est, aut raro, aut numquam gementem audies, lacrimantem videbis. Putes, si attendas, aut sui oblitum, aut ablutum a culpis. In signis scurrilitas, in fronte hilaritas, vanitas apparet in incessu. Pronus ad iocum, facilis ac promptus in risu. Cunctis quippe quae in se contemptibilia, et ideo tristia noverat, a memoria rasis, bonisque, si qua sentit in se, adunatis vel simulatis ante oculos mentis, dum nil cogitat nisi quod libet, nec attendit si licet, iam risum tenere, iam ineptam laetitiam dissimulare non valet. Vt enim vesica collecto turgida vento punctoque forata exiguo, si stringitur, crepitat dum detumescit, ac ventus egrediens non passim effusus, sed strictim emissus crebros quosdam sonitus reddit, sic monachus, ubi vanis scurrilibusque cor suum cogitationibus impleverit, propter disciplinam silentii non inveniens ventus vanitatis qua plenius egrediatur inter angustias faucium per cachinnos excutitur. Saepe vultum pudibundus abscondit, claudit labia, dentes stringit; ridet tamen nolens, cachinnat invitus. Cumque os pugnis obstruxerit suis, per nares adhuc sternutare auditur.",
      "It is characteristic of the proud that they always look out for pleasure and shun sadness, in accordance with the saying: The heart of fools is where there is mirth. So it is that the monk who has already descended two degrees of pride and through inquisitiveness has arrived at levity, when he sees the joy for which he is always on the look out constantly interrupted by the distress which he feels at the sight of good in others, chafes under the sense of humiliation and takes refuge in a suggestion of unreal comfort. Henceforth he restrains his inquisitiveness on that side on which his own worthlessness and his neighbour's excellence are shown to him, and turns his whole attention to the other side. He may thus mark only too carefully those things in which he seems to be the better man, and may hide those in which others surpass him, and so may put away all thought of sorrow and remain always merry. It thus happens that silly merriment soon gains sole possession of the man whom joy and sorrow alternately claim. I set this before you as the third degree of pride; now note the marks by which you may detect it, either in yourself or in anyone else. You seldom or never hear a man of this kind groan, or see him shed tears. You will think, if you consider, that his faults are either forgotten or forgiven. His gestures are those of a buffoon, his look that of a coxcomb, his step that of a dandy. He is always making jokes, and never loses a chance of laughing. He cuts out of his mind all discreditable and therefore distressing recollections, and concentrates his mental vision on his real or pretended merits. As he thinks of nothing but what is pleasant without considering whether it is lawful, he can neither restrain laughter nor hide his unseasonable merriment. A bladder swells when it is full of wind, but if a small hole is pricked in it and it is squeezed, it creaks as it collapses, and the air does not rush out at once, but is gradually expelled and gives out frequent intermittent sounds. In like manner when a monk has filled his mind with vapid and vulgar thoughts, the flood of folly which cannot, owing to the rule of silence, find full and free vent, is thrown but from his narrow jaws in guffaws of laughter. He constantly hides his face as if ashamed, compresses his lips, and clenches his teeth. He laughs loudly without meaning to do so, and even against his will. And when he has stopped his mouth with his fists he is frequently heard to sneeze.",
      "It is proper to the proud always to seek joyful things and to avoid sad ones, according to that: The heart of fools, where gladness is. Whence also the monk who has already descended two degrees of pride, while through curiosity he comes down to lightness of mind, when he sees the joy which he always seeks frequently interrupted by the sadness which he contracts from another’s goods, impatient of his humiliation, flees to the counsel of a false consolation. From that part, finally, by which his cheapness to himself and another’s excellence is shown, he restrains curiosity, that he may transfer himself wholly into the contrary part, so that he may more curiously note that in which he himself seems to excel, always conceal that in which the other excels, so that while he avoids what is thought sad, gladness may be continued. And so it is made, that him whom joy and sadness were claiming in turn, unfitting gladness alone begins to possess. In this I constitute the third degree for you: take by which signs you may catch it either in yourself or in another. Him who is of this sort you will hear groaning either rarely or never, you will see weeping. You would think, if you attend, either forgetful of himself, or washed from faults. In signs scurrility, on the brow cheerfulness, vanity appears in the walk. Prone to a joke, easy and ready in laughter. For all things which he had known contemptible in himself, and therefore sad, scraped from memory, and goods, if he feels any in himself, united or simulated before the eyes of the mind, while he thinks nothing except what pleases, nor attends whether it is allowed, he is already unable to hold laughter, already unable to dissimulate unfitting gladness. For as a bladder swollen with gathered wind and pierced by a small point, if it is squeezed, crackles while it deflates, and the wind going out, not poured everywhere but sent out strictly, returns certain frequent sounds, so the monk, when he shall have filled his heart with vain and scurrilous thoughts, the wind of vanity not finding, because of the discipline of silence, where it may go out more fully, is shaken out through guffaws among the narrows of the jaws. Often ashamed he hides the face, closes the lips, binds the teeth; yet he laughs unwilling, guffaws uninvited. And when he shall have blocked the mouth with his fists, he is still heard to sneeze through the nostrils.",
    ),
  ]),
  ch("cap-13", 13, "Caput XIII", "De quarto gradu, qui est iactantia", [
    one(
      "p41",
      "41",
      "At postquam vanitas crescere et vesica grossescere coeperit necesse est ut ampliori foramine, laxato sinu, ventositas eructuetur; aliquin rumpetur. Sic monachus, inepta redundante laetitia, dum risu vel signis eam aperire non sufficit, in Heliu verba prorumpit: En venter meus quasi mustum absque spiraculo, quod lagunculas novas dirumpit. Aut loquetur ergo, aut rumpetur. Plenus est enim sermonibus, et coarctat eum spiritus uteri sui. Esurit et sitit auditores, quibus suas iactitet vanitates, quibus omne quod sentit effundat, quibus qualis et quantus sit innotescat. Inventa autem occasione loquendi, si de litteris sermo exoritur, vetera proferuntur et nova; volant sententiae, verba resonant ampullosa. Praevenit interrogantem, non quaerenti respondet. Ipse quaerit, ipse solvit, et verba collocutoris imperfecta praecidit. Cum autem, pulsato signo, necesse est interrumpi colloquium, horam longam, breve queritur intervallum; quaerit licentiam ut ad fabulas revertatur post horam, non ut quempiam aedificet, sed ut scientiam iactet. Aedificare potest, sed non aedificare intendit. Non curat te docere vel a te docere ipse quod nescit, sed ut scire sciatur quod scit. Quod si de religione agitur, statim visiones et somnia proferuntur. Deinde laudat ieiunia, commendat vigilias, super omnia orationes exaltat; de patientia, de humilitate, aut de singulis virtutibus plenissime, sed vanissime disputat, ut tu scilicet, si audieris, dicas quod ex abundantia cordis os loquitur, et quia bonus homo de bono thesauro suo profert bona. Si ad ludicra sermo convertitur, in his quanto assuetior, tanto loquacior invenitur. Dicas, si audias, rivum vanitatis, fluvium esse scurrilitatis os eius, ita ut severos quoque et graves animos in levitatem concitet risus. Et ut totum in brevi colligam in multiloquio nota iactantiam. In hoc habes quartum gradum et descriptum et nominatum. Fuge rem, et tene nomen. Hac eadem cautela iam accede ad quintum, quem nomino singularitatem.",
      "But when vanity increases, and the bladder begins to be inflated, it becomes necessary to loosen the belt and allow a larger outlet for the air, otherwise the bladder will burst. So the monk who is unable to discharge his superabundant store of unseemly merriment by laughter or by gesture, breaks forth with the words of Elihu, My belly is as new wine which wanteth vent, which bursteth the new vessels. He must speak out or break down. For he is full of matter to speak of, and the spirit of his bowels constraineth him. He hungers and thirsts for hearers, at whom he may throw his banalities, to whom he may pour out his feelings, and let them know what a fine fellow he is. But when he has found his opportunity of speaking — if the conversation turns on literary matters, old and new points are brought forward; he airs his ideas in loud and lofty tone. He interrupts his questioner and answers before he is asked. He himself puts the question and gives the answer, nor does he even allow the person to whom he is talking to finish his remarks. When the striking of the silence gong puts a stop to conversation, he complains that a full hour is not a sufficient allowance, and asks for indulgence that he may go on with his gossip after the time for it is over — not to add to the knowledge of any one else, but to boast of his own. He has the power but not the purpose of giving useful information. His care is not to teach you or to learn from you things which he does not know, but that the extent of his learning may be made known. If the subject under discussion is religion, he is forward with his vision and his dreams. He upholds fasting, prescribes vigils, and maintains the paramount importance of prayer. He enlarges at great length but with excessive conceit on patience, humility and all the virtues in turn, with the intention that you on hearing him should say, Out of the abundance of the heart the mouth speaketh, and that a good man out of his good treasure bringing forth good things. If the talk turns on light subjects he becomes more loquacious, because he is on more familiar ground. If you hear the torrent of his conceit you may say that his mouth is a fount of such buffoonery as to move even strict and sober monks to light laughter. To put it shortly, mark his swagger in his chatter. In this you have the name and description of the fourth degree of pride. Remember the description and avoid the reality. With this warning, go on to the fifth degree which I call eccentricity.",
      "But after vanity has begun to grow and the bladder to thicken it is necessary that by a wider hole, the fold having been loosened, the windiness be belched; otherwise it will be burst. So the monk, unfitting gladness overflowing, while he does not suffice to open it by laughter or signs, breaks forth into Elihu’s words: Behold my belly is as must without a breathing-hole, which bursts new flasks. He will therefore either speak, or be burst. For he is full of speeches, and the spirit of his belly constrains him. He hungers and thirsts for hearers, to whom he may boast his vanities, to whom he may pour out everything he feels, to whom of what sort and how great he is may become known. And an occasion of speaking having been found, if speech arises about letters, old things are brought forth and new; sentences fly, swollen words resound. He comes before the one asking, he answers the one not seeking. He himself asks, he himself looses, and he cuts off the interlocutor’s unfinished words. When however, the sign having been struck, it is necessary that the colloquy be interrupted, he complains that the hour is long, the interval brief; he seeks license that he may return to fables after the hour, not that he may edify anyone, but that he may boast knowledge. He can edify, but he does not intend to edify. He does not care to teach you or himself to learn from you what he does not know, but that what he knows may be known to be known. But if it is treated of religion, at once visions and dreams are brought forth. Then he praises fasts, commends vigils, exalts prayers above all; about patience, about humility, or about the single virtues he disputes most fully, but most vainly, so that you namely, if you shall have heard, may say that from the abundance of the heart the mouth speaks, and that a good man from his good treasure brings forth goods. If speech is turned to play, in these by how much more accustomed, by so much more talkative he is found. You would say, if you should hear, that a stream of vanity, a river of scurrility is his mouth, so that he stirs even severe and grave minds into lightness of laughter. And that I may gather the whole in brief: in much-speaking mark boasting. In this you have the fourth degree both described and named. Flee the thing, and hold the name. By this same caution now approach the fifth, which I name singularity.",
    ),
  ]),
  ch("cap-14", 14, "Caput XIV", "De quinto gradu superbiae, qui dicitur singularitas", [
    one(
      "p42",
      "42",
      "Turpe est ei, quo se supra ceteros iactat, si non plus ceteris aliquid agat, per quod ultra ceteros appareat. Proinde non sufficit ei quod communis monasterii regula vel maiorum cohortantur exempla. Nec tamen melior esse studet, sed videri. Non melius vivere, sed videri vincere gestit, quatenus dicere possit: Non sum sicut ceteri hominum. Plus sibi blanditur de uno ieiunio, quod ceteris prandentibus facit, quam si cum ceteris septem dies ieiunaverit. Commodior sibi videtur una oratiuncula peculiaris, quam tota psalmodia unius noctis. Inter prandendum crebro solet oculos iactare per mensas, ut si quem minus comedere viderit, victum se doleat, et incipiat idipsum sibi crudeliter subtrahere, quod necessarium victui indulgendum praeviderat, plus gloriae metuens detrimentum quam famis cruciatum. Si quem macriorem, si quem pallidiorem perspexerit, vilem se aestimat, numquam requiescit. Et quoniam vultum ipse suum videre non potest, qualem scilicet se intuentibus offert, manus, quas potest, et brachia spectans, palpat costas, humeros attrectat et lumbos, ut secundum quod corporis sui membra, vel minus, vel satis exilia probat, pallorem ac colorem oris discernat. Ad omnia denique sua strenuus, ad communia piger. Vigilat in lecto, dormit in choro; cumque aliis psallentibus ad vigilias tota nocte dormitet, post vigilias, aliis in claustro quiescentibus, solus in oratorio remanet: excreat et tussit, gemitibus ac suspiriis aures foris sedentium de angulo implet. Cum autem ex his quae singulariter, sed inaniter agit, apud simpliciores eius opinio excreverit, qui profecto opera probant quae cernunt, sed unde prodeant non discernunt, dum miserum beatificant, in errorem inducunt.",
      "A man who prides himself on being better than his fellow-men thinks it a disgrace if he does not do something more than they do, whereby his superiority may be apparent. Therefore the general rule of the monastery and the example of its senior members are not enough for him. Yet his anxiety is not to be, but to be seen to be better than they. His effort is not to lead a better life but visibly to surpass others, so that he may be able to say, I am not as the rest of men. He takes more credit to himself for having once gone without a meal while others were having theirs, than he does in having shared in a fast of seven days. One little private prayer of his own seems to him more commendable than the recitation of all the Psalms set for an entire night. At mealtime he has a habit of casting his eyes all round the tables, and if he sees anyone eating less than himself, he is annoyed at being outdone. He begins severely to cut down the amount of food which he had hitherto recognized as his necessary ration, because he is more afraid of loss of credit than of the pangs of hunger. If he catches sight of anyone more shrunken and sallow than himself, he cannot rest under what he considers to be a disgrace. And, since he cannot see his own face and the aspect under which he presents himself to onlookers, he examines his hands and arms which he can see, beats his breast, taps his shoulders and loins, and from the more or less attenuated condition of his limbs forms an opinion as to the paleness or colour of his face. But while active in all his private devotions, he is indolent in public worship. He keeps vigil while in bed, and goes to sleep in his stall. He sleeps all night while others are chanting the early Psalms. When the vigil is over, and the other monks are resting in the cloister, he alone lingers in the oratory. He coughs and spits, and the ears of those sitting outside are filled with the sighs and groans from his corner. By his silly and singular action he has established a high reputation with his more simple brethren, who quite approve what they, see of his doings, though they do not detect their motive, and, by the commendation which they bestow on him, they aid and abet the wretched man's mistake.",
      "It is shameful to him, by which he casts himself above the rest, if he does not do something more than the rest, through which he may appear beyond the rest. Hence it is not enough for him that the common rule of the monastery or the examples of the greater ones exhort. Nor nevertheless does he study to be better, but to be seen. He does not long to live better, but to be seen to win, so that he may be able to say: I am not like the rest of men. He flatters himself more from one fast, which he makes while the rest are dining, than if with the rest he shall have fasted seven days. One peculiar little prayer seems more convenient to him than the whole psalmody of one night. During dining he is accustomed frequently to cast eyes through the tables, that if he shall have seen someone eat less, he may grieve himself beaten, and begin cruelly to withdraw from himself the very thing which he had foreseen must be indulged as necessary to food, fearing more the loss of glory than the torment of hunger. If he shall have looked upon someone thinner, someone paler, he estimates himself cheap, he never rests. And since he cannot see his own face, of what sort namely he offers himself to those looking, looking at the hands, which he can, and the arms, he feels the ribs, handles the shoulders and loins, that according as he proves the members of his body either less or enough wasted, he may discern the paleness and colour of the mouth. Finally strenuous toward all his own, sluggish toward common things. He watches in bed, sleeps in choir; and when with others psalming at vigils he dozes the whole night, after vigils, others resting in the cloister, he remains alone in the oratory: he hawks and coughs, from a corner he fills the ears of those sitting outside with groans and sighs. When however from these things which he does singularly but emptily his reputation has grown among the simpler, who indeed prove the works which they discern, but do not discern whence they proceed, while they beatify the miserable one, they lead him into error.",
    ),
  ]),
  ch("cap-15", 15, "Caput XV", "De sexto gradu superbiae, id est arrogantia", [
    one(
      "p43",
      "43",
      "Credit quod audit, laudat quod agit, et quid intendat non attendit. Obliviscitur intentionem, dum amplectitur opinionem. Quique de omni alia re plus sibi credit quam aliis, de se solo plus aliis credit quam sibi, ut iam non verbotenus aut sola operum ostentatione suam praeferat religionem, sed intimo cordis credat affectu se omnibus sanctiorem; et quidquid de se laudatum agnoverit, non ignorantiae aut benevolentiae laudatoris, sed suis meritis arroganter ascribit. Vnde post singularitatem, sextum sibi gradum iure arrogantia vindicavit. Post hanc praesumptio invenitur, in qua septimus gradus constituitur.",
      "He believes what he hears, praises his own action, and pays no attention to the motive. He welcomes a favourable opinion and forgets its purpose. And he who in everything else puts more trust in himself than in other men, attaches more weight to the opinions of others about him than to his own. So not only does he think that he exhibits superior religion on account of his verbal profession or special display of piety, but in his inmost heart he considers himself more holy than any one else. And if he knows that he is praised for anything, he ascribes it, not to the ignorance or the kindliness of the person who commends him, but, with much conceit, to his own deserts. So after eccentricity, conceit has made good its claim to be the sixth degree. After it, audacity shows itself — and in it the seventh degree consists.",
      "He believes what he hears, praises what he does, and does not attend to what he intends. He forgets the intention, while he embraces the opinion. And he who about every other thing believes himself more than others, about himself alone believes others more than himself, so that now he may not prefer his religion in word only or by mere display of works, but by the inmost affection of the heart may believe himself holier than all; and whatever praised about himself he shall have recognized, he arrogantly ascribes not to the ignorance or benevolence of the praiser, but to his merits. Whence after singularity, arrogance has rightly claimed the sixth degree for itself. After this presumption is found, in which the seventh degree is constituted.",
    ),
  ]),
  ch("cap-16", 16, "Caput XVI", "De septimo gradu superbiae, qui est praesumptio", [
    one(
      "p44",
      "44",
      "Qui enim alios se praecellere putat, quomodo plus de se quam de aliis non praesumat? Primus in conventibus residet, in consiliis primus respondet; non vocatus accedit, non iussus se intromittit; reordinat ordinata, reficit facta. Quidquid ipse non fecerit aut ordinaverit, nec recte factum, nec pulchre aestimat ordinatum. Iudicat iudicantes, praeiudicat iudicaturis. Si, cum tempus advenerit, non promoveatur ad prioratum, suum abbatem aut invidum iudicat, aut deceptum. Quod si mediocris ei aliqua oboedientia iniuncta fuerit, indignatur, aspernatur, arbitrans se non esse minoribus occupandum, qui se ad maiora sentit idoneum. Sed qui sic promptulus possibile est eum aliquando non errare. Ad praelatum autem pertinet errantem arguere. Sed quomodo culpam suam confitebitur, qui nec esse putat, nec putari culpabilis patitur? Propterea cum ei culpa imputatur, crescit, non amputatur. Si ergo, cum argutus fuerit, declinare cor eius videris in verba malitiae, in octavum gradum, qui dicitur defensio peccatorum, noveris corruisse.",
      "For if a man thinks himself superior to others, is it likely that he will not push himself in front of them? He is the first to take his seat at meetings, the first to intervene in debate. He comes forward without invitation, and with no introduction but his own; he re-opens questions that have been settled, and goes again over work that has been done. He considers that nothing that he has not himself designed and carried out, has been properly organized or satisfactorily executed. He criticises those who sit in judgment, and tells them what their decisions should be. If, when the time comes for the appointment of a Prior, he is not promoted to the office, he is certain that his Abbot is either jealous or mistaken. But if some less important duty is assigned to him, he is displeased and contemptuous, for, as he feels himself qualified for greater work, he thinks that he ought not to be employed in smaller matters. But it is inconceivable that a man who, with more rashness than readiness, is very anxious to undertake all sorts of work, should not sometimes make mistakes. And it is the duty of the Abbot to reprove such a one for his error. But how will he confess his fault, if he neither thinks himself, nor will allow others to think him, worthy of censure? Therefore when his fault is pointed out to him, it is not removed but grows worse. So if, when he is reproved, you see him incline his heart to wicked words, you may know that he has sunk to the eighth degree, which is called defence of wrong-doing.",
      "For he who thinks that he excels others, how does he not presume more about himself than about others? First he sits in gatherings, in counsels he answers first; not called he approaches, not ordered he puts himself in; he reorders things ordered, remakes things made. Whatever he himself shall not have done or ordered, he estimates neither rightly done, nor beautifully ordered. He judges those judging, prejudges those about to be judged. If, when the time shall have arrived, he is not promoted to the priorate, he judges his abbot either envious, or deceived. But if some middling obedience shall have been enjoined on him, he is indignant, he scorns, judging that he is not to be occupied with lesser things, who feels himself fit for greater. But he who is so ready, it is possible that he sometimes not err. And it belongs to the prelate to argue the erring one. But how will he confess his fault, who neither thinks himself to be, nor suffers himself to be thought, culpable? Therefore when a fault is imputed to him, it grows, it is not cut off. If therefore, when he shall have been argued, you shall have seen his heart decline into words of malice, you will have known that he has rushed down into the eighth degree, which is called defence of sins.",
    ),
  ]),
  ch("cap-17", 17, "Caput XVII", "De octavo gradu, qui est defensio peccatorum", [
    one(
      "p45",
      "45",
      "Multis vero modis fiunt excusationes in peccatis. Aut enim dicit qui se excusat: \"Non feci\", aut: \"Feci quidem, sed bene feci\", aut si male \"Non multum male\"; aut si multum male; \"Non mala intentione\". Si autem et de illa, sicut Adam vel Eva, convincitur, aliena suasione, excusare se nititur. Sed qui procaciter etiam aperta defendit, quando occultas et malas cogitationes, cordi suo advenientes, humiliter revelaret abbati?",
      "There are many ways in which defence is made for sin. A man either says 'I did it not' or 'I no doubt did it, but I acted rightly in so doing', or 'I may have acted wrongly but not to a serious extent,' or, 'If I was seriously wrong, I had no bad intention'. If, however, he, like Adam and Eve, is proved to be guilty, he attempts to excuse himself on the ground that he was tempted by some one else. But if a man unblushingly defends even open sins, will he ever humbly disclose to the Abbot the hidden evil thoughts which come into his mind?",
      "But excuses in sins are made in many ways. For either he who excuses himself says: I did not do, or: I did indeed, but I did well, or if badly, Not much badly; or if much badly, Not with a bad intention. But if he is convicted also about that, like Adam or Eve, he strives to excuse himself by another’s persuasion. But he who shamelessly defends even open things, when would he humbly reveal hidden and evil thoughts, arriving at his heart, to the abbot?",
    ),
  ]),
  ch("cap-18", 18, "Caput XVIII", "De nono gradu superbiae, qui est simulata confessio", [
    one(
      "p46",
      "46",
      "Licet vero genera haec excusationis eatenus mala iudicentur, quatenus ore prophetico verba malitiae appellentur, multo tamen periculosior est fallax ac superba confessio, quam pervicax et obstinata defensio. Nonnulli enim, cum de apertioribus arguuntur, scientes, si se defenderent, quod sibi non crederetur, subtilius inveniunt argumentum defensionis, verba respondentes dolosae confessionis. Est quippe, ut scriptum est, qui nequiter humiliat se, et interiora eius plena sunt dolo. Vultus demittitur, prosternitur corpus; aliquas sibi lacrimulas extorquent, si possunt; vocem suspiriis, verba gemitibus interrumpunt. Nec solum qui eiusmodi est obiecta non excusat, sed ipse quoque culpam exaggerat, ut dum impossibile aliquid aut incredibile culpae suae ore ipsius additum audis, etiam illud, quod ratum putabas, discredere possis, et ex eo quod falsum esse non dubitas, dum confitetur, in dubium veniat quod quasi certum tenebatur. Dumque affirmant quod credit nolunt, confitendo culpam defendunt, et aperiendo tegunt, quando et confessio laudabiliter sonat in re, et adhuc iniquitas occultatur corde, quatenus magis ex humilitate quam ex veritate confiteri putet qui audit aptans eis illud Scripturae: Iustus in principio sermonis accusator est sui. Malunt enim apud homines veritate periclitari quam humilitate, cum apud Deum periclitentur utrimque. Aut si adeo culpa manifesta sit, quod nulla penitus tegi versutia possit, nihilominus tamen vocem, non cor paenitentis assumunt, qua notam, non culpam deleant, dum ignorantiam manifestae transgressionis decore recompensant publicae confessionis.",
      "But although defences of this kind are considered so wrong that they are called by the Prophet evil words a false and perverse confession is much more dangerous than even a brazen and stubborn defence. For there are some who, when they are reproved for rather conspicuous offences, and know that no excuse which they may offer will be accepted, have recourse to a more cunning form of defence — they reply by a deceitful confession. For there is, as it is written, one that humbleth himself wickedly and his interior is full of deceit. The countenance is downcast — the body is prostrate. They exact from themselves, if they are able to do so, some tears. They interrupt their speech by sighs and intersperse their words with groans. A man of this description not only offers no excuse for the offences with which he is charged, but himself even exaggerates his guilt. He does this that you, when you hear him make a further accusation against himself of some impossible or inconceivable crime, may be disposed to disbelieve even that of which you thought him guilty — and thus, from the fact that he makes a confession which you fully believe to be false, some doubt may be thrown on that which you held to be almost certain. And when these men make a statement the acceptance of which they do not desire, by their confession they excuse, and by their disclosures they conceal, their fault. Their confession sounds praiseworthy in the mouth, but wickedness is hidden in the heart; so that he who hears may think that the confession is made with more humility than accuracy, and may apply to them that Scriptural saying, The righteous man at the beginning of his speech is his own accuser. accuser of himself'. For in the sight of men they would rather be thought wanting in truthfulness than in humility while in the sight of God they are lacking in both. But if their guilt is so clear that by no subterfuge can it be entirely concealed, they nevertheless adopt the tone, though not the spirit of repentance, and by this means remove the mark, though not the reality of their guilt, as they make up for ignoring an open offence by the credit of a public confession.",
      "Although these kinds of excuse are judged evil insofar as they are called by the prophetic mouth words of malice, yet a deceitful and proud confession is much more dangerous than a stubborn and obstinate defence. For some, when they are argued about more open things, knowing that if they defended themselves it would not be believed to them, find more subtly an argument of defence, answering the words of a deceitful confession. For there is, as it is written, one who wickedly humbles himself, and his interiors are full of deceit. The countenance is sent down, the body is prostrated; they extort some little tears for themselves, if they can; they interrupt the voice with sighs, the words with groans. Nor does he who is of this kind only not excuse things objected, but he himself also exaggerates the fault, so that while you hear something impossible or incredible added to his fault from his own mouth, you can disbelieve even that which you thought ratified, and from that which you do not doubt to be false, while he confesses, that which was held as certain may come into doubt. And while they affirm what they do not wish to be believed, by confessing they defend the fault, and by opening they cover, when both the confession sounds praiseworthily in the thing, and still iniquity is hidden in the heart, so that he who hears may think them to confess more from humility than from truth, fitting to them that of Scripture: The just at the beginning of speech is the accuser of himself. For they prefer to be endangered among men by truth than by humility, although before God they are endangered on both sides. Or if the fault is so manifest that it can be covered by no cunning at all, they nevertheless assume the voice, not the heart, of one repenting, by which they may wipe the mark, not the fault, while they recompense the ignorance of a manifest transgression by the decorum of a public confession.",
    ),
    one(
      "p47",
      "47",
      "Gloriosa res humilitas, qua ipsa quoque superbia palliare se appetit, ne vilescat! Sed haec cito tergiversatio a praelato deprehenditur, si ad hanc superbam humilitatem non leviter flectitur, quo magis dissimulet culpam vel differat poenam. Vasa figuli probat fornax, et tribulatio vere paenitentes discernit. Qui enim veraciter paenitet, laborem paenitentiae non abhorret, sed quidquid sibi pro culpa quam odit iniungitur, tacita conscientia patienter amplectitur. In ipsa quoque oboedentia duris ac contrariis rebus obortis, quibuslibet irrogatis iniuriis, sustinens non lassescit, ut in quarto gradu stare se indicet humilitatis. Cuius vero simulata confessio est, una vel levi contumelia aut exigua poena interrogatus, iam humilitatem simulare, iam simulationem dissimulare non potest. Murmurat, frendet, irascitur, nec in quarto stare humilitatis, sed in nonum superbiae gradum corruisse probatur, qui, secundum quod descriptus est, recte simulata confessio appellari potest. Quanta putas tunc confusio sit in corde superbi, cum fraus decipitur, pax amittitur, laus minuitur, nec culpa diluitur? Tandem notatur ab omnibus, iudicatur ab omnibus, eoque vehementius omnes indignatur, quo falsum conspiciunt quidquid de eo prius opinabantur. Tunc opus est praelato, ut eo minus illi parcendum putet, quo magis omnes offenderet, si uni parceret.",
      "A fine sort of humility is this, in which pride seeks to array itself, that it may not lose caste! But this double-dealing is soon detected by the Abbot, unless he is to some extent imposed upon by this haughty humility, and thus induced to pass over the fault or postpone the penalty. The furnace trieth the potter's vessels, and distress reveals the real penitent. For the man who is truly penitent does not shrink from the trouble of repentance. Whatever is prescribed to him on account of the fault which he detests, he accepts with submissive and silent acquiescence. And if through this very obedience unexpected hardships arise, and he thereby sustains injuries that were not intended, he does not give up, so that he may show that he has his place in the fourth degree of humility. But he whose confession is unreal, when he is confronted with a slight rebuke, or trifling penalty, is unable either to feign humility or to conceal his dissimulation. He murmurs, gnashes his teeth and loses his temper, and it becomes clear that, so far from standing in the fourth degree of humility, he has fallen into the ninth degree of pride, which from the above description of it, may well be called sham confession. How great, think you, must be the proud man's consternation when his deceit is detected, his pardon forfeited, and his fault not condoned? He is at last found out and condemned by all and the general indignation is all the greater when men see how erroneous was their former judgment of him. It is then the duty of the Abbot to be less ready to pardon him, because the forgiveness of one would be an offence to all.",
      "A glorious thing is humility, by which pride itself also desires to cloak itself, lest it become cheap! But this turning-about is quickly caught by the prelate, if he is not lightly bent to this proud humility, by which he may more hide the fault or defer the punishment. The furnace proves the potter’s vessels, and tribulation discerns those truly penitent. For he who truly repents does not shrink from the labour of penitence, but whatever is enjoined on him for the fault which he hates, he embraces patiently with a silent conscience. In the obedience itself also, hard and contrary things having arisen, any injuries having been inflicted, sustaining he does not weary, that he may indicate himself to stand in the fourth degree of humility. But of whom the confession is simulated, questioned by one even light insult or a slight punishment, he already cannot simulate humility, already cannot hide the simulation. He murmurs, he gnashes, he is angered, and is proved not to stand in the fourth of humility, but to have rushed down into the ninth degree of pride, which, according to what has been described, can rightly be called a simulated confession. How great do you think then is the confusion in the heart of the proud, when the fraud is deceived, peace is lost, praise is lessened, nor is the fault washed? At last he is noted by all, judged by all, and he is the more vehemently indignant at all, the more they look upon as false whatever they formerly opined about him. Then there is need for the prelate, that he think him the less to be spared, the more he would offend all, if he spared one.",
    ),
  ]),
  ch("cap-19", 19, "Caput XIX", "De decimo gradu superbiae, qui est rebellio", [
    one(
      "p48",
      "48",
      "Hic, nisi eum miseratio superna respiciat, ut — quod valde talibus difficile est — universorum iudiciis tacitus acquiescat, frontosus mox et impudens factus, tanto deterius quanto desperatius in decimum gradum per rebellionem corruit, quique prius latenter arrogans fratres contempserat, iam patenter inoboediens etiam magistrum contemnit.",
      "Unless by a merciful intervention of Providence this man quietly accepts the unanimous verdict — a thing which it is very difficult for such persons to do — he soon becomes shameless and defiant, and more hopelessly degenerate, and sinks through rebellion into the tenth degree, so that he who had hitherto by his conceit treated his brethren with veiled discourtesy, now by his disobedience shows open contempt for authority.",
      "Here, unless heavenly pity look back upon him, so that — what is very difficult for such — he silently acquiesce in the judgments of all, soon made brazen and shameless, by so much worse as more desperately he rushes through rebellion into the tenth degree, and he who previously, secretly arrogant, had despised the brothers, now openly disobedient despises even the master.",
    ),
    one(
      "p49",
      "49",
      "Sciendum autem est, quod omnes gradus, quos in duodecim partitus sum, in tres tantummodo colligi possunt, ut in sex superioribus contemptus fratrum, in quatuor sequentibus contemptus magistri, in duobus, qui restant, consummetur contemptus Dei. Notandum quoque, quod hi duo ultimi superbiae gradus, qui et humilitatis ascendendo primi inveniuntur, sicut extra congregationem ascendendi sunt, ita in congregatione descendi non possunt. Quod autem ante ascendi debeant, ex hoc aperte intelligi datur, quod de tertio gradu in Regula legitur: Tertius, inquit, gradus est, ut quis pro Dei amore omni oboedentia se subdat maiori. Si ergo in tertio gradu subiectio collocatur, quae procul dubio fit, quando primum novitius conventui sociatur, consequens est quod duo iam anteriores transcensi intelligantur. Denique ubi fratrum concordiam ac magistri sententiam monachus spernit, quid ultra in monasterio, nisi scandalum facit?",
      "For it should be observed that all the degrees — which I have divided into twelve — may be arranged in three groups; in the first six there is disrespect to the brethren, in the four that follow defiance of authority, while the last two show complete contempt for God. And it should also be noted that, just as the first two degrees in the ascending scale of humility must be attained before entering the community so the last downward steps in pride, which are their counterpart, cannot be taken whilst in it. That the first two degrees must be previously passed, the language of the Rule makes clear. For it says that 'The third degree is that anyone for love of God should submit with entire obedience to his superior. Therefore if this submission, which beyond doubt is made when the novice enters the convent, is assigned to the third degree, the necessary presumption is that the two preceding degrees have been passed. Therefore when a monk scorns alike the harmony of the brethren and the decision of his ruler, what more can he do in the monastery except cause scandal?",
      "It is to be known, however, that all the degrees which I have divided into twelve can be gathered into three only, so that in the six higher the contempt of the brothers, in the four following the contempt of the master, in the two that remain the contempt of God is consummated. It is to be noted also that these two last degrees of pride, which also in ascending are found first of humility, as they are to be ascended outside the congregation, so they cannot be descended in the congregation. But that they ought to be ascended before is given to be understood openly from this, that about the third degree it is read in the Rule: The third, it says, degree is, that one for the love of God subject himself by every obedience to a greater. If therefore in the third degree subjection is placed, which beyond doubt is done when first a novice is associated to the convent, it is consequent that the two already earlier are understood as crossed. Finally, where a monk spurns the concord of the brothers and the sentence of the master, what further does he do in the monastery, except make scandal?",
    ),
  ]),
  ch("cap-20", 20, "Caput XX", "De undecimo gradu superbiae, qui est libertas peccandi", [
    one(
      "p50",
      "50",
      "Post decimum itaque gradum, qui rebellio dictus est, expulsus vel egressus de monasterio statim excipitur ab undecimo. Et tunc ingreditur vias, quae videntur hominibus bonae, quarum finis -nisi forte Deus eas sibi saepierit- demerget eum in profundum inferni, id est in contemptum Dei. Impius, siquidem, cum venerit in profundum malorum, contemnit. Potest autem undecimus gradus appellari libertas peccandi, per quam monachus, cum iam nec magistrum videt quem timeat, nec fratres quos revereatur, tanto securius quanto liberius sua desideria implere delectatur, a quibus in monasterio tam pudore quam timore prohibebatur. Sed etsi iam vel fratres vel abbatem non timet, nondum tamen Dei penitus formidine caret. Hanc ratio, tenuiter adhuc submurmurans, voluntati proponit, nec sine aliqua dubitatione quaeque primum illicita perfecit; sed, sicut is qui vadum tentat, pedetentim, non cursim, vitiorum gurgitem intrat.",
      "So after the tenth degree — which has been described as 'rebellion' the man is at once caught in the eleventh. He then enters those paths which are attractive to men, at the end of which (unless God shall perchance have interposed some barrier for his protection) he will be plunged into the nethermost hell — that is into contempt of God. For the wicked man when he is come into the depth of evils, contemneth. The eleventh degree may be called freedom to sin, since in it a monk, who sees that he has now neither a ruler to fear nor brethren to respect, can safely and freely give full play to his own desires, which shame as well as fear prevented him from doing while in the monastery. But although he no longer dreads his brethren or his Abbot, he has not yet lost all awe of God. Reason, some faint echo of which still remains, places this check upon his inclination, and it is not without some hesitation that he enters on his sinful course, and, like a man who is trying to ford a stream, steps rather than runs into the torrent of vice.",
      "After the tenth degree, then, which has been called rebellion, expelled or having gone out from the monastery he is at once taken up by the eleventh. And then he enters ways that seem good to men, whose end — unless perhaps God shall have hedged them for himself — will sink him into the deep of hell, that is into the contempt of God. The impious, indeed, when he shall have come into the deep of evils, despises. And the eleventh degree can be called liberty of sinning, through which the monk, when now he sees neither a master whom he may fear, nor brothers whom he may revere, is delighted to fulfill his desires by so much more securely as more freely, from which in the monastery he was prohibited as much by shame as by fear. But even if he now does not fear either the brothers or the abbot, he does not yet wholly lack the dread of God. Reason, still thinly murmuring underneath, proposes this to the will, nor without some hesitation does he first accomplish whatever illicit things. but, as he who tries a ford, step by step, not at a run, he enters the whirlpool of vices.",
    ),
  ]),
  ch("cap-21", 21, "Caput XXI", "De duodecimo gradu superbiae, qui est consuetudo peccandi", [
    one(
      "p51",
      "51",
      "At postquam terribili Dei iudicio prima flagitia impunitas sequitur, experta voluptas libenter repetitur, repetita blanditur. Concupiscentia reviviscente, sopitur ratio, ligat consuetudo. Trahitur miser in profundum malorum, traditur captivus tyrannidi vitiorum, ita ut carnalium voragine desideriorum absorptus, suae rationis divinique timoris oblitus, dicat insipiens in corde suo: Non est Deus. Iam indifferenter libitis pro licitis utitur, iam ab illicitis cogitandis, patrandis, investigandis animus, manus vel pedes non prohibentur; sed quidquid in cor, in buccam, ad manum venerit, machinatur, garrit, et operatur, malevolus, vaniloquus, facinorosus. Quemadmodum denique ascensis his omnibus gradibus, corde iam alacri et absque labore pro bona consuetudine iustus currit ad vitam, sic descensis impius eisdem, pro malo usu non se ratione gubernans, non timoris freno retentans, intrepidus festinat ad mortem. Medii sunt quo fatigantur, angustiantur, quo nunc metu cruciati gehennae, nunc pristina retardati consuetudine, descendendo vel ascendendo laborant. Supremus tantum et infimus currunt absque impedimento et absque labore. Ad mortem hic, ad vitam ille festinat; alter alacrior, alter proclivior. Illum alacrem charitas, hunc proclivem cupiditas facit. In altero amor, in altero stupor laborem non sentit. In illo denique perfecta charitas, in isto consummata iniquitas foras mittit timorem. Illi veritas, huic caecitas dat securitatem. Potest ergo duodecimus gradus appellari consuetudo peccandi, qua Dei metus amittitur, contemptus incurritur.",
      "But when, by the awful judgment of God, his first offences have been unpunished, the pleasure that he has derived from them is freely repeated, and its repetition engrosses him. Lust is quickened, reason lulled, and habit becomes bondage. The wretched man is drawn into the abyss of evil, made prisoner to the despotic rule of vice, and so overwhelmed by the whirlpool of his carnal desires that he forgets alike his own reason and the fear of God, and says madly in his heart, There is no God. He now, without scruple, puts pleasure in the place of law, his mind, his hands and his feet are no longer forbidden to consider, execute and pursue courses that are unlawful; but whatever comes to his heart, his mouth or his hand, he designs, discusses and carries out, with evil intent, idle utterance, and sinful action. 1. Ps. xiii.",
      "But after, by the terrible judgment of God, impunity follows the first outrages, the pleasure experienced is gladly repeated, the repeated flatters. Desire reviving, reason is lulled, custom binds. The miserable one is dragged into the deep of evils, is handed over captive to the tyranny of vices, so that, swallowed by the whirlpool of carnal desires, forgetful of his reason and of divine fear, the unwise says in his heart: There is no God. Already he uses liked things indifferently for allowed ones, already the mind, hands or feet are not prohibited from thinking, perpetrating, tracking illicit things; but whatever has come into the heart, into the mouth, to the hand, he machinates, chatters, and works, malevolent, vain-speaking, criminal. Finally, as, all these degrees having been ascended, with a heart already eager and without labour because of good custom the just man runs to life, so the impious, the same having been descended, not governing himself by reason because of bad use, not holding back by the bridle of fear, hastens fearless to death. There are middle ones by which they are wearied, anguished, by which now tortured by fear of gehenna, now retarded by former custom, they labour descending or ascending. Only the highest and the lowest run without impediment and without labour. To death this one, to life that one hastens; the one more eager, the other more sloping-down. Charity makes that one eager, cupidity this one sloping-down. In the one love, in the other stupor does not feel labour. Finally in that one perfect charity, in this one consummated iniquity, sends fear outside. To that one truth, to this one blindness gives security. The twelfth degree, then, can be called the custom of sinning, by which the fear of God is lost, contempt is incurred.",
    ),
  ]),
  ch("cap-22", 22, "Caput XXII", "Quomodo orandum pro desperatis et mortuis secundum animam", [
    one(
      "p52",
      "52",
      "Pro tali iam, inquit Ioannes apostolus, non dico ut quis oret. Sed numquid dicis, o Apostole, ut quis desperet? Immo gemat qui illum amat. Non praesumat orare, nec desistat plorare. Quid est quod dico? An forte ullum remanet spei refugium, ubi oratio non invenit locum? Audi credentem, sperantem, nec tamen orantem: Domine, inquit, si fuisses hic, frater meus non fuisset mortuus. Magna fides, qua credit sua praesentia Dominum mortem prohibere potuisse, si adfuisset. Modo autem quid? Absit ut quem credidit vivum potuisse servare, mortuum dubitet posse resuscitare: Sed et nunc, inquit, scio, quia quaecumque poposceris a Deo, dabit tibi Deus. Deinde quaerenti ubi posuissent eum, respondet: Veni et vide. Quamobrem? O Martha, magna nobis fidei tuae insignia tribuis; sed quomodo cum tanta fide diffidis? Veni, inquis, et vide. Cur, si non desperas, non sequeris, et dicis: \"Et resuscita\"? Si autem desperas, cur magistrum sine causa fatigas? An forte fides aliquando recipit, quod oratio non praesumit? Denique appropinquantem cadaveri prohibes, et dicis: Domine iam foetet: quatriduanus enim est. Desperando dicis hoc, an dissimulando? Sic quippe ipse Dominus post resurrectionem finxit se longius ire, cum mallet cum discipulis remanere. O sanctae mulieres Christi familiares, si fratres vestrum amatis, cur eius misericordiam non flagitatis, de cuius potentia dubitare, pietate diffidere non potestis? Respondent: \"Sic melius tamquam non orantes oramus, sic efficacius quasi diffidentes confidimus. Exhibemus fidem, perhibemus affectum: scit ipse, cui non est opus ut aliquid dicatur, quid desideremus. Scimus quidem quod omnia potest; sed hoc tam grande miraculum, tam novum, tam inauditum, etsi eius subest potentiae, multum tamen excedit universa merita humilitatis nostrae. Sufficit nobis potentiae locum, pietati dedisse occasionem, malentes patienter exspectare quid velit, quam impudenter quaerere quod forsitan nolit. Denique quod nostris meritis deest, verecundia fortasse supplebit\". Petri quoque post gravem lapsum lacrimam quidem video, sed precem non audio; nec tamen de indulgentia dubito.",
      "For such an one, says John the Apostle, I do not say that any one shall pray. But sayest thou, O Apostle, that no one may Hope? Surely he who loves that man may groan. He ventures not to pray, he need not forbear to weep. What is this that I say that perchance there remains the resource of hope, where prayer has no place? Take an instance of one who believes and hopes, yet does not pray. Lord, she says, if thou hadst been here, my brother had not died. What mighty faith to believe that by His presence the Lord could have prevented death. But what comes next? It is inconceivable that she should doubt that He whom she believed could have kept him alive, was unable to raise him from the dead. But now, says she, I know that whatsoever thou wilt ask of God, God will give it thee. Then when He asks where they had laid him, she replies, Come and see. Why dost thou stop there? O Martha, thou dost afford to us ample evidence of thy faith; but, as it is so great, why dost thou hesitate? Come, sayest thou, and see. Why, if thou art not without hope, dost not thou go further and say, 'and raise him up'? If, on the other hand, thou art in despair, why givest thou the Master unreasonable trouble? Is it perchance that faith sometimes obtains that for which we dare not pray? Then as He approaches the corpse thou dost object to His coming near, and sayest, Lord, by this time he stinketh, for he hath been dead four days. Was this said in despair, or in pretence? In somewhat the same sense the Lord Himself after His Resurrection made as though he would go further, while His intention was to remain with the disciples. O ye holy women, intimate friends of Christ, if ye love your brother why do ye not appeal to the compassion of Him of whose power and pity ye cannot entertain a doubt? Their answer is, We pray all the better for not uttering a prayer, we trust the more completely for concealing our confidence. We show our faith and suppress our feelings. He who has no need of any information Himself knows what we desire. We indeed know that He can do all things; but a miracle so great, so unprecedented, though it is within His power, far surpasses anything that in our insignificance we deserve. It is enough for us to have afforded scope for his power and an opportunity for His pity and we prefer patiently to await His will than daringly to demand that which it may not be His pleasure to give. And finally our modesty may perhaps obtain for us something more than we deserve. And I observe that Peter wept after his serious fall, but I do not hear that he prayed. Yet I have no doubt about his pardon.",
      "For such a one already, says John the apostle, I do not say that anyone should pray. But do you say, O Apostle, that anyone should despair? Nay, let him groan who loves him. Let him not presume to pray, nor let him cease to weep. What is it that I say? Does perhaps any refuge of hope remain, where prayer does not find a place? Hear one believing, hoping, and yet not praying: Lord, she says, if you had been here, my brother would not have been dead. Great faith, by which she believes that by his presence the Lord could have forbidden death, if he had been present. But now what? Far be it that she should doubt that he whom she believed able to keep alive is able to raise the dead: But even now, she says, I know that whatever things you shall have asked from God, God will give you. Then to him asking where they had placed him, she answers: Come and see. For what reason? O Martha, you grant us great insignia of your faith; but how with so great faith do you distrust? Come, you say, and see. Why, if you do not despair, do you not follow, and say: ‘And raise’? But if you despair, why do you weary the master without cause? Or does faith perhaps sometimes receive what prayer does not presume? Finally you prohibit him approaching the corpse, and you say: Lord already he stinks: for he is of four days. Do you say this by despairing, or by dissembling? For so the Lord himself after the resurrection pretended to go further, when he preferred to remain with the disciples. O holy women, familiars of Christ, if you love your brothers, why do you not demand his mercy, of whose power you cannot doubt, of whose piety distrust? They answer: ‘So better we pray as not praying, so more efficaciously we trust as distrusting. We exhibit faith, we bear affection: he himself knows, to whom there is no need that anything be said, what we desire. We know indeed that he can all things; but this so great miracle, so new, so unheard, even if it lies under his power, nevertheless much exceeds all the merits of our humility. It suffices us to have given place to power, occasion to piety, preferring patiently to wait what he may will, than impudently to seek what perhaps he would not. Finally what is lacking to our merits, shame will perhaps supply.’ Of Peter also after a heavy fall I see a tear indeed, but I do not hear a prayer; nor nevertheless do I doubt about indulgence.",
    ),
    one(
      "p53",
      "53",
      "Disce et in Matre Domini magnam in mirabilibus fidem habere, in magna fide verecundiam retinere. Disce verecundia decorare fidem, reprimere praesumptionem. Vinum, inquit, non habent. Quam breviter, quam reverenter suggessit, unde pie sollicita fuit! Et ut discas in huiusmodi magis pie gemere quam petere praesumptuose, pietatis aestum pudoris temperans umbra, conceptam precis fiduciam verecunde suppressit. Non frontose accessit, non palam locuta est, ut audacter coram omnibus diceret: \"Obsecro, fili, deficit vinum, contristantur convivae, confunditur sponsus; ostende quid possis\". Sed licet haec aut multo plura pectus aestuans, fervens loqueretur affectus, privatim tamen potentem pia Filium mater adivit, non potentiam tentans, sed voluntatem explorans: Vinum, inquit, non habent. Quid modestius? Quid fidelius? Non defuit pietati fides, voci gravitas, efficacia voto. Si ergo illa, cum mater sit, matrem se oblita non audet petere miraculum vini, ego vile mancipium, cui permagnum est Filii simul ad Matris esse vernaculum, qua fronte praesumo pro vita petere quatriduani?",
      "Learn further from the Mother of the Lord how to have full faith in the marvellous and in the full- ness of faith to preserve modesty. Learn to adorn faith with modesty and to avoid presumption. They have no wine, says she. With what brevity, with what reverence she made a suggestion on a matter in which she felt a kindly anxiety. And that you may learn in similar circumstances rather to heave a sympathetic sigh than to venture to make a direct request, she concealed her eager earnestness under a shade of shyness, and modestly refrained from expressing the confidence she felt in prayer. She did not come boldly forward with a clear request, and say straight out before every one 'I appeal to thee, my son: the wine has run short, the guests are annoyed, the bridegroom is dismayed — show what thou canst do'. But although as her breast was burning with these and many other thoughts, she might have expressed her feelings warmly, yet the devout Mother quietly approached her mighty Son, not to test His power but to discover His will. They have no wine, says she. How could she better have combined modesty and confidence? There was no lack of faith in her devotedness, of seriousness in her voice, or of earnestness in her desire. She, however, though she was His Mother, waived the claims of kinship, and did not venture to ask for a miraculous supply of wine. With what face, then, can I, a common slave, to whom it is a high honour to be in the service at once of the Son and of the Mother, presume to ask for the life of one who has been dead for four days?",
      "Learn also in the Mother of the Lord to have great faith in wonders, in great faith to retain shame. Learn by shame to decorate faith, to repress presumption. They have no wine, she says. How briefly, how reverently she suggested that about which she was piously anxious! And that you may learn in things of this kind rather to groan piously than to ask presumptuously, tempering the heat of piety by the shade of pudor, she modestly suppressed the conceived trust of a prayer. She did not approach brazenly, she did not speak openly, that she might boldly say before all: ‘I beseech, son, the wine fails, the guests are saddened, the bridegroom is confounded; show what you can.’ But although a breast boiling, a burning affection, was speaking these or much more, yet privately the pious mother approached the powerful Son, not testing power, but exploring will: They have no wine, she says. What more modest? What more faithful? Faith was not lacking to piety, gravity to the voice, efficacy to the vow. If therefore she, though she is mother, having forgotten herself to be mother does not dare to ask a miracle of wine, I, a cheap slave, to whom it is very great to be a house-servant of the Son together with the Mother, with what forehead do I presume to ask for the life of one of four days?",
    ),
    one(
      "p54",
      "54",
      "Duo etiam in Evangelio caeci visum, alter accepisse, alter recepisse leguntur: alter quem amiserat, alter quem numquam habuerat; unus scilicet excaecatus, alter vero caecus natus. Sed quo excaecatus, miserabilibus mirisque clamoribus miram misericordiam meruit; qui vero caecus natus, tanto misericordius quanto mirabilius nullis suis precibus praeventum, sui illuminatoris beneficium nihilominus sensit. Illi denique dictum est: Fides tua te salvum fecit; huic autem non. Duos quoque recens mortuos, tertium iam quatriduanum, lego resuscitatos; solam tamen, in domo adhuc positam, precibus patris; duos autem ex insperata magnitudine pietatis.",
      "It is also recorded in the Gospel that two blind men had sight given or restored to them one the sight which he had lost, the other that which he had never possessed for one had become blind, the other had been so born. But the one who had lost his sight earned marvellous mercy by piteous and persistent prayer, while the one who was born blind received from his divine enlightener a yet more merciful and more marvellous benefit without any previous petition from himself. To him it was afterwards said, Thy faith hath made thee whole. because his object was to contrast the circumstances of the miracles, and to show that the lesser one was the direct answer to prayer. I also read of the raising of two persons who had lately died and of a third one who had been dead for four days; but only the one who was still lying in her father's house was thus raised at his prayer the other two were restored by a great and unexpected manifestation of mercy.",
      "Two also in the Gospel are read to have received sight, the one to have received, the other to have received back: the one what he had lost, the other what he had never had; one namely blinded, the other truly born blind. But he who was blinded merited marvellous mercy by miserable and marvellous cries; but he who was born blind, by so much more mercifully as more marvellously, nevertheless felt the benefit of his illuminator, forestalled by no prayers of his own. To that one finally it was said: Your faith has made you safe; but to this one not. Two also recently dead, a third already of four days, I read raised; only the one, still placed in the house, by the prayers of the father; but the two from the unhoped-for greatness of piety.",
    ),
    one(
      "p55",
      "55",
      "Simili etiam forma si contigerit, quod Deus avertat, aliquem de nostris fratribus, non in corpore, sed in anima mori, quamdiu adhuc inter nos erit, pulsabo et ego meis qualiscumque peccator, pulsabo et fratrum precibus Salvatorem. Si revixerit, lucrati erimus fratrem, sin vero non mereamur exaudiri, ubi iam vel tolerare vivos, vel tolerari a vivis non poterit, sed incipiet efferri, semper quidem fideliter gemo, sed iam non ita fiducialiter oro. Non aperte audeo dicere: \"veni, Domine, suscita mortuum nostrum\"; corde tamen suspenso tremulus intus clamare non cesso: \"Si forte, si forte, si forte desiderium pauperum exaudiet Dominus, praeparationem cordis eorum audiet auris eius\", et illud: Numquid mortuis facies mirabilia, aut medici suscitabunt, et confitebuntur tibi? Et de quatriduano: Numquid narrabit aliquis in sepulcro misericordiam tuam, et veritatem tuam in perditione? Potest interim Salvator, si vult, improvise et insperate occurrere nobis, lacrimisque portantium motus, non precibus, mortui vitam reddere vivis, aut certe iam sepultum revocare mortuis. Mortuum autem dixerim illum, qui sua peccata defendens, in octavum iam corruit gradum. A mortuo enim, tamquam qui non est, perit confessio. Post decimum vero, quo tertius est ab octavo, iam effertur in libertatem peccandi, quando expellitur a consortio monasterii. At postquam quartum transierit, iam recte quatriduanus dicitur, dum in quintum decidens per consuetudinem sepelitur.",
      "So if, in like manner, it should happen (which may God avert) that any one of our brethren should meet not bodily but spiritual death; as long as he shall be with us, I, sinner that I am, will persistently assail the Saviour with my prayers and with those of the brethren. If he revives, we shall have gained our brother; but if we do not deserve to be heeded and the time comes when he cannot endure those who are alive, or be endured by them, but must be carried out for burial, I go on faithfully with my mourning, though I cannot pray with so much confidence. I dare not say openly, 'Lord raise up our dead brother' but with anxious heart and inward trembling I cease not to cry out. If by any chance at all the Lord shall listen to the desire of the poor, his ear will heed the readiness of their hearts. And there is that saying. Wilt thou show wonders to the dead? or shall physicians raise to life and give praise to thee? and concerning him who has been dead four days. Shall anyone in the sepulchre declare thy mercy; and thy truth in destruction? Meanwhile it is possible that the Saviour may be pleased to meet us unforeseen and unexpectedly, and moved by the tears, not by the prayers of the bearers, to restore the dead man to those who live, or actually to recall from among the dead one who is already buried. But I should describe as dead the man who by excusing his sins, has already come down to the eighth degree. For praise perisheth from the dead as from one who does not exist. But after the tenth degree, which is third from the eighth, he is already being carried out into liberty to sin, when he is expelled from the monastic community. But after he has passed the fourth degree he is rightly said to be 'four days dead', and when he falls into the fifth degree of habitual sin he is already buried.",
      "In a similar form also if it shall have happened, which God avert, that someone of our brothers die, not in the body but in the soul, as long as he will still be among us, I also will knock with mine, a sinner of whatever sort, I will knock also with the brothers’ prayers upon the Saviour. If he shall have lived again, we shall have gained a brother, but if we do not deserve to be heard, where already he will not be able either to tolerate the living, or to be tolerated by the living, but will begin to be carried out, I always indeed groan faithfully, but I no longer pray so trustingly. I do not dare to say openly: ‘come, Lord, raise our dead’; yet with a suspended heart, trembling within, I do not cease to cry: ‘If perhaps, if perhaps, if perhaps the Lord will hear the desire of the poor, his ear will hear the preparation of their heart,’ and that: Will you make wonders for the dead, or will physicians raise, and they will confess to you? And about the four-days-dead: Will anyone tell your mercy in the sepulchre, and your truth in perdition? The Saviour can meanwhile, if he wills, unforeseen and unhoped meet us, and moved by the tears of those carrying, not by prayers, give back the life of the dead to the living, or certainly already buried recall him from the dead. But I would have said him dead, who, defending his sins, has already rushed down into the eighth degree. For from a dead man, as from one who is not, confession perishes. But after the tenth, which is third from the eighth, he is already carried out into liberty of sinning, when he is expelled from the companionship of the monastery. But after he shall have crossed the fourth, he is already rightly called of four days, while falling into the fifth he is buried through custom.",
    ),
    one(
      "p56",
      "56",
      "Absit autem a nobis, ut etiam pro talibus, etsi palam non praesumimus, vel in cordibus nostris orare cessemus, cum Paulus eos quoque lugeret, quos sine paenitentia mortuos sciret. Etsi enim a communibus orationibus ipsi se excludunt, sed ab affectibus omnino non possunt. Viderint tamen in quanto periculo sint, pro quibus Ecclesia palam orare non audeat, quae fidenter etiam pro Iudaeis, pro haereticis, pro gentilibus orat. Cum enim in Parasceve nominatim oretur pro quibuslibet malis, nulla tamen mentio fit de excommunicatis.",
      "But God forbid that we should cease to pray in our hearts for such even as these though we do not venture to do so openly, as Paul also mourned for those whom he knew to have died impenitent. For although they shut themselves out from our united prayers, they cannot altogether do so from their effects. They should nevertheless realize the great danger which those incur whom the Church, which prays confidently for Jews, heretics and heathen, dares not to mention in her worship. For when on Good Friday prayer is expressly offered for certain wicked persons, no mention is made of those who are excommunicated.",
      "But far be it from us that even for such, although we do not presume openly, we should cease to pray even in our hearts, since Paul also was mourning those whom he knew dead without penitence. For even if they exclude themselves from common prayers, yet they cannot altogether from affections. Yet let them have seen in how great danger they are, for whom the Church does not dare to pray openly, who prays confidently even for Jews, for heretics, for gentiles. For when on Parasceve it is prayed by name for any evils, yet no mention is made of the excommunicated.",
    ),
  ]),
  ch("admonitio", 23, "Conversio ad eum ad quem scribit", "To Godfrey, on why pride was described", [
    one(
      "p57",
      "57",
      "Dicis forte, frater Godefride, me aliud quam tu quaesisti, quam ipse promisi, tandem exhibuisse, cum pro gradibus humilitatis, superbiae gradus videar descripsisse. Ad quod ego: non potui docere nisi quod didici. Non putavi congruum me describere ascensiones, qui plus descendere quam ascendere novi. Proponat tibi beatus Benedictus gradus humilitatis, quos ipse prius in corde suo disposuit; ego quid proponam non habeo, nisi ordinem meae descensionis. In quo tamen, si diligenter inspicitur, via forsitan ascensionis reperitur. Si enim tibi Romam tendenti homo inde veniens obviaret, quaesitus viam, quid melius quam illam, qua venit, ostenderet? Dum castella, villas et urbes, fluvios ac montes, per quos transierit, nominat, suum denuntians iter, tuum tibi praenuntiat, ita ut eadem loca recognoscas eundo, quae ille pertransiit veniendo. In hac similiter nostra descensione gradus ascensorios fortasse reperies, quos ascendendo melius tu in tuo corde quam in nostro codice leges.",
      "You may perhaps say, brother Godfrey, that in thus describing the degrees of pride instead of those of humility, I seem to have gone beyond your request and my own tardy promise. To which my answer is that I was unable to teach anything but what I had learned. I did not think it seemly on my part to speak of an ascent, since I am aware that my own movements have been in a downward rather than in an upward direction. Blessed Benedict may set before you the degrees of humility, for he has previously set His own heart upon them. I have nothing to put before you, unless it be my own downward course. Yet if that is carefully examined, the way to go up may haply be found therein. For if as you are going towards Rome, a man who is coming thence meets you, and you ask him the way, how can he better tell you than by pointing out the route that he has followed? In naming the castles, villages, cities, rivers and mountains which he has passed, he records his own journey and foretells yours, so that as you go on you may recognize the places that he has passed. In like manner in this downward course of mine you may possibly discover the upward steps, and as you ascend, may you study them to more purpose in your own heart than in my book.",
      "You say perchance, brother Godfrey, that I have at last exhibited something other than you asked, than I myself promised, since instead of the degrees of humility I seem to have described the degrees of pride. To which I: I could not teach except what I learned. I did not think it fitting that I describe ascents, I who know more to descend than to ascend. Let blessed Benedict set before you the degrees of humility, which he himself first arranged in his heart; I have nothing to set before, except the order of my descent. In which nevertheless, if it is diligently inspected, the way of ascent is perhaps found. For if to you heading to Rome a man coming from there should meet, asked the way, what better than that by which he came would he show? While he names the castles, villages and cities, rivers and mountains through which he shall have passed, announcing his journey, he foreannounces yours to you, so that going you may recognize the same places which he passed through coming. In this our descent similarly you will perhaps find the ascending degrees, which by ascending you will better read in your heart than in our codex.",
      [
        {
          kind: "theology",
          title: "the Rome road",
          body: "Bernard will not describe ascents he has not made. The same road is known by the one coming down. Mills’s ‘book’ is codice — the close line keeps codex, the written ladder versus the heart.",
        },
      ],
    ),
  ]),
];
